dyncam_base VARCHAR(1),
dyncam_dom VARCHAR(20),
dyncam_tab VARCHAR(5),
dyncam_form VARCHAR(20),
dyncam_pk VARCHAR(1),
dyncam_alb VARCHAR(1),
dyncam_sch VARCHAR(1),
dyncam_sch_b VARCHAR(1),
dyncam_lis VARCHAR(1),
dyncam_ric VARCHAR(1),
dyncam_numord NUMERIC(5),
dyncam_name_p VARCHAR(30),
dyncam_tnf VARCHAR(30),
dyncam_fnf VARCHAR(30),
dyncam_op VARCHAR(10),
dyncam_val NUMERIC(7),
dyncam_val_s VARCHAR(2000),
dyncam_tipo VARCHAR(10),
 primary key (DYNENT_NAME,DYNENT_TYPE,DYNCAM_NAME));

CREATE VIEW DYNCAM AS
(SELECT
DYNENT_NAME,
DYNENT_TYPE,
DYNCAM_NAME,
DYNCAM_DESC,
DYNCAM_BASE,
DYNCAM_DOM,
DYNCAM_TAB,
DYNCAM_FORM,
DYNCAM_PK,
DYNCAM_ALB,
DYNCAM_SCH,
DYNCAM_SCH_B,
DYNCAM_LIS,
DYNCAM_RIC,
DYNCAM_NUMORD,
DYNCAM_NAME_P,
DYNCAM_TNF,
DYNCAM_FNF,
DYNCAM_OP,
DYNCAM_VAL,
DYNCAM_VAL_S
FROM DYNCAM_GEN WHERE DYNCAM_TIPO <> 'T' OR DYNCAM_TIPO IS NULL);

CREATE OR REPLACE RULE dyncam_ins AS ON INSERT TO dyncam
DO INSTEAD
dynent_name,
dynent_type,
dyncam_name,
dyncam_desc,
dyncam_base,
dyncam_dom,
dyncam_tab,
dyncam_form,
dyncam_pk,
dyncam_alb,
dyncam_sch,
dyncam_sch_b,
dyncam_lis,
dyncam_ric,
dyncam_numord,
dyncam_name_p,
dyncam_tnf,
dyncam_fnf,
dyncam_op,
dyncam_val,
dyncam_val_s)
VALUES (
NEW.dynent_name,
NEW.dynent_type,
NEW.dyncam_name,
NEW.dyncam_desc,
NEW.dyncam_base,
NEW.dyncam_dom,
NEW.dyncam_tab,
NEW.dyncam_form,
NEW.dyncam_pk,
NEW.dyncam_alb,
NEW.dyncam_sch,
NEW.dyncam_sch_b,
NEW.dyncam_lis,
NEW.dyncam_ric,
NEW.dyncam_numord,
NEW.dyncam_name_p,
NEW.dyncam_tnf,
NEW.dyncam_fnf,
NEW.dyncam_op,
NEW.dyncam_val,
NEW.dyncam_val_s);

CREATE OR REPLACE RULE dyncam_upd AS ON UPDATE TO dyncam
DO INSTEAD
UPDATE dyncam_gen
SET dynent_name = NEW.dynent_name,
dynent_type = NEW.dynent_type,
dyncam_name = NEW.dyncam_name,
dyncam_desc = NEW.dyncam_desc,
dyncam_base = NEW.dyncam_base,
dyncam_dom = NEW.dyncam_dom,
dyncam_tab = NEW.dyncam_tab,
dyncam_form = NEW.dyncam_form,
dyncam_pk = NEW.dyncam_pk,
dyncam_alb = NEW.dyncam_alb,
dyncam_sch = NEW.dyncam_sch,
dyncam_sch_b = NEW.dyncam_sch_b,
dyncam_lis = NEW.dyncam_lis,
dyncam_ric = NEW.dyncam_ric,
dyncam_numord = NEW.dyncam_numord,
dyncam_name_p = NEW.dyncam_name_p,
dyncam_tnf = NEW.dyncam_tnf,
dyncam_fnf = NEW.dyncam_fnf,
dyncam_op = NEW.dyncam_op,
dyncam_val = NEW.dyncam_val,
dyncam_val_s = NEW.dyncam_val_s
WHERE	dynent_name = OLD.dynent_name AND
dynent_type = OLD.dynent_type AND
dyncam_name = OLD.dyncam_name;

CREATE OR REPLACE RULE dyncam_del AS ON DELETE TO dyncam
DO INSTEAD
DELETE FROM dyncam_gen
WHERE dynent_name = OLD.dynent_name AND
dynent_type = OLD.dynent_type AND
dyncam_name = OLD.dyncam_name;

