create or replace view v_cais_tit as 
select cais.caisim, cais.descat, 
cais.tiplavg, tab5nord titnord, cais.titcat, 
cais.codliv1, cais.codliv2, cais.codliv3, cais.codliv4,
cais1.descat desliv1, cais2.descat desliv2, cais3.descat desliv3, cais4.descat desliv4,
cais.caisord, cais.quaobb, cais.acontec, cais.isarchi,
case when (select count(*) from cais cais5 where cais5.codliv1=cais.caisim or cais5.codliv2=cais.caisim or cais5.codliv3=cais.caisim or cais5.codliv4=cais.caisim)=0 then '1' else '2' end isfoglia,
case when cais.codliv4 is not null then 5 when cais.codliv3 is not null then 4 when cais.codliv2 is not null then 3 when cais.codliv1 is not null then 2 else 1 end numliv,
(case when cais.tiplavg=4 then '0' else to_char(cais.tiplavg,'FM9') end) || 
(case when tab5nord is null then '00000' else lpad(to_char(tab5nord*100,'FM99999'),5,'0') end) || 
(case when tab5tip is null then '000' else lpad(tab5tip,3,'0') end) || 
(case when cais.caisord is null then '000' else lpad(to_char(cais.caisord,'FM999'),3,'0') end) ||
(case when substr(tab1desc,1,1)='2' then 
(case when cais.codliv4 is not null then 
rpad(cais1.descat,30,'*') || rpad(cais2.descat,30,'*') ||
rpad(cais3.descat,30,'*') || rpad(cais4.descat,30,'*') || rpad(cais.descat,30,'*') 
when cais.codliv3 is not null then 
rpad(cais1.descat,30,'*') || rpad(cais2.descat,30,'*') || 
rpad(cais3.descat,30,'*') || rpad(cais.descat,30,'*') || '******************************'
when cais.codliv2 is not null then
rpad(cais1.descat,30,'*') || rpad(cais2.descat,30,'*') || 
rpad(cais.descat,30,'*') || '******************************' || '******************************'
when cais.codliv1 is not null then
rpad(cais1.descat,30,'*') || rpad(cais.descat,30,'*') || 
'******************************' || '******************************' || '******************************'
else rpad(cais.descat,30,'*') || '******************************' || 
'******************************' || '******************************' || '******************************' end)
else
(case when cais.codliv4 is not null then 
rpad(cais.codliv1,30,'*') || rpad(cais.codliv2,30,'*') ||
rpad(cais.codliv3,30,'*') || rpad(cais.codliv4,30,'*') || rpad(cais.caisim,30,'*') 
when cais.codliv3 is not null then 
rpad(cais.codliv1,30,'*') || rpad(cais.codliv2,30,'*') || 
rpad(cais.codliv3,30,'*') || rpad(cais.caisim,30,'*') || '******************************'
when cais.codliv2 is not null then
rpad(cais.codliv1,30,'*') || rpad(cais.codliv2,30,'*') || 
rpad(cais.caisim,30,'*') || '******************************' || '******************************'
when cais.codliv1 is not null then
rpad(cais.codliv1,30,'*') || rpad(cais.caisim,30,'*') || 
'******************************' || '******************************' || '******************************'
else rpad(cais.caisim,30,'*') || '******************************' || 
'******************************' || '******************************' || '******************************' end) end) numord
from cais left outer join tab5 on (CAIS.TITCAT = TAB5.TAB5TIP and TAB5.TAB5COD = 'G_j05')
left outer join cais cais1 on (cais1.caisim=cais.codliv1)
left outer join cais cais2 on (cais2.caisim=cais.codliv2)
left outer join cais cais3 on (cais3.caisim=cais.codliv3)
left outer join cais cais4 on (cais4.caisim=cais.codliv4)
inner join tab1 on (tab1cod='G_057' and tab1tip=1);

create or replace view V_IMPR_SOGGETTI as 
select codimp2 codimp, codtim, (cast('Legale rappresentante' as varchar(100))) incarico, nomtim, cftim, legini datini, legfin datfin, notleg 
from impleg, teim 
where codtim=codleg 
union 
select codimp3 codimp, codtim, (cast('Direttore tecnico' as varchar(100))) incarico, nomtim, cftim, dirini datini, dirfin datfin, notdte 
from impdte, teim 
where codtim=coddte 
union 
select codimp4 codimp, codtim, tab1desc incarico, nomtim, cftim, iniazi datini, finazi datfin, notazi 
from impazi, teim, tab1 
where codtim=codtec and tab1cod like 'Ag007' and tab1tip=incazi 
union
select codimp, codtim, tab1desc incarico, nomtim, cftim, incini datini, incfin datfin, notcol 
from g_impcol, teim, tab1 
where codtim=codtec and tab1cod like 'G_039' and tab1tip=inctip;

create or replace view v_soggetti_verifiche as 
(select codimp2 codimp, codtim, (cast('Legale rappresentante' as varchar(100))) incarico, nomtim, cftim, nomimp, cfimp, cgentim
from impleg, teim, impr 
where codtim=codleg and codimp2=codimp and (tipimp is null or tipimp<>3)
union
select codime9 codimp, codtim, (cast('Legale rappresentante' as varchar(100))) incarico, nomtim, cftim, nomdic, (select cfimp from impr where codimp = coddic),  cgentim
from impleg, teim, impr ,ragimp
where codtim=codleg and codimp2=coddic and codime9=codimp and tipimp=3)
UNION
(select codimp3 codimp, codtim, (cast('Direttore tecnico' as varchar(100))) incarico, nomtim, cftim, nomimp, cfimp, cgentim
from impdte, teim , impr 
where codtim=coddte  and codimp3=codimp and (tipimp is null or tipimp<>3)
union 
select codime9 codimp, codtim, (cast('Direttore tecnico' as varchar(100))) incarico, nomtim, cftim, nomdic, (select cfimp from impr where codimp = coddic), cgentim
from impdte, teim , impr ,ragimp
where codtim=coddte and codimp3=coddic and codime9=codimp and tipimp=3)
UNION
(select codimp4 codimp, codtim, tab1desc incarico, nomtim, cftim, nomimp, cfimp, cgentim
from impazi, teim, tab1 , impr 
where codtim=codtec and tab1cod = 'Ag007' and tab1tip=incazi and codimp4=codimp and (tipimp is null or tipimp<>3)
union
select codime9 codimp, codtim, tab1desc incarico, nomtim, cftim, nomdic, (select cfimp from impr where codimp = coddic), cgentim
from impazi, teim, tab1 , impr ,ragimp
where codtim=codtec and tab1cod = 'Ag007' and tab1tip=incazi and codimp4=coddic and codime9=codimp and tipimp=3)
UNION
(select c.codimp, codtim, tab1desc incarico, nomtim, cftim, nomimp, cfimp, cgentim
from g_impcol c, teim, tab1, impr i
where codtim=codtec and tab1cod = 'G_039' and tab1tip=inctip and c.codimp=i.codimp and (tipimp is null or tipimp<>3)
union
select codime9, codtim, tab1desc incarico, nomtim, cftim, nomdic, (select cfimp from impr where codimp = coddic), cgentim
from g_impcol c, teim, tab1 , impr i ,ragimp
where codtim=codtec and tab1cod = 'G_039' and tab1tip=inctip and c.codimp=coddic and codime9=i.codimp and tipimp=3);

create view v_accesslog as
select app, utente, datini from accesslog where stato = 1
union
select app, utente, datfin from accesslog where stato = 1;

create view v_accesslog_sez as
select distinct app, datini, (select min(datini) from v_accesslog al1 where al1.datini > al.datini and al.app=al1.app ) as datfin
from v_accesslog al
where exists(select 1 from v_accesslog al2 where al2.datini > al.datini and al.app=al2.app );

create view v_accesslog_count as 
select v_accesslog_sez.app, v_accesslog_sez.datini, v_accesslog_sez.datfin, count(*) as cnt,
round( (DATE_PART('day', v_accesslog_sez.datfin - v_accesslog_sez.datini)) * 1440 ) as minuti
from v_accesslog_sez, accesslog 
where accesslog.datini < v_accesslog_sez.datfin and accesslog.datfin > v_accesslog_sez.datini 
and v_accesslog_sez.app =  accesslog.app
group by v_accesslog_sez.app, v_accesslog_sez.datini, v_accesslog_sez.datfin;

create view v_accesslog_usr as
select cnt, utente, sysute, app, datini, datfin, round( (DATE_PART('day', datfin - datini)) * 1440 ) as minuti, stato
from accesslog;

create view v_prosp_impr_g_ as select annimpr.imprtip as annimpr_imprtip, impr.codimp as impr_codimp, impr.nomimp as impr_nomimp, impr.tipimp as impr_tipimp from annimpr, impr where ( ( annimpr.imprcod=impr.cfimp ) or ( annimpr.imprcod=impr.pivimp ) ) and ( impr.cfimp is not null or impr.pivimp is not null) group by annimpr.imprtip, impr.codimp, impr.nomimp, impr.tipimp order by annimpr.imprtip, impr.codimp, impr.nomimp, impr.tipimp;

