create view v_uffint_g2funz_vld as ( select cast(g2funz.codei as varchar(16)) as codein, cast(g2funz.incfun as numeric(7)) as inc, cast(tab1.tab1desc as varchar(200)) as inc_descr, cast('UFFINT' as varchar(30)) as ufficio_padre_entita, cast('G2FUNZ' as varchar(30)) as entita_campo_rif, cast(g2funz.numfun as numeric(12)) as id_key, g2funz.codfun as codice, g2funz.dinfun as data_inizio, g2funz.dtefun as data_fine from g2funz, tab1 where tab1.tab1cod='A2144' and tab1.tab1tip=g2funz.incfun and (g2funz.incfun is not null) and ((g2funz.dinfun is null) or (g2funz.dtefun is null) or (g2funz.dtefun>=g2funz.dinfun)) and (g2funz.codfun is not null) );

create view v_impr_sogg_vld as ( select cast(impleg.codimp2 as varchar(16)) as codimp, cast(-40 as numeric(7)) as inc, cast('Legale rappresentante' as varchar(200)) as inc_descr, cast('IMPR' as varchar(30)) as impresa_padre_entita, cast('IMPLEG' as varchar(30)) as entita_campo_rif, cast(impleg.id as numeric(12)) as id_key, impleg.codleg as codice, impleg.nomleg as denominazione, impleg.legini as data_inizio, impleg.legfin as data_fine from impleg where (impleg.codimp2 is not null) and ((impleg.legini is null) or (impleg.legfin is null) or (impleg.legfin>=impleg.legini)) and (impleg.codleg is not null)
union
select cast(impdte.codimp3 as varchar(16)) as codimp, cast(-30 as numeric(7)) as inc, cast('Direttore tecnico' as varchar(200)) as inc_descr, cast('IMPR' as varchar(30)) as impresa_padre_entita, cast('IMPDTE' as varchar(30)) as entita_campo_rif, cast(impdte.id as numeric(12)) as id_key, impdte.coddte as codice, impdte.nomdte as denominazione, impdte.dirini as data_inizio, impdte.dirfin as data_fine from impdte where (impdte.codimp3 is not null) and ((impdte.dirini is null) or (impdte.dirfin is null) or (impdte.dirfin>=impdte.dirini)) and (impdte.coddte is not null)
union
select cast(impazi.codimp4 as varchar(16)) as codimp, cast(impazi.incazi as numeric(7)) as inc, cast(tab1.tab1desc as varchar(200)) as inc_descr, cast('IMPR' as varchar(30)) as impresa_padre_entita, cast('IMPAZI' as varchar(30)) as entita_campo_rif, cast(impazi.numazi as numeric(12)) as id_key, impazi.codtec as codice, impazi.nomtec as denominazione, impazi.iniazi as data_inizio, impazi.finazi as data_fine from impazi, tab1 where tab1.tab1cod='Ag007' and tab1.tab1tip=impazi.incazi and (impazi.incazi is not null) and ((impazi.iniazi is null) or (impazi.finazi is null) or (impazi.finazi>=impazi.iniazi)) and (impazi.codtec is not null) );

