-- Creazione INDICI -------------------------
---------------------------------------------
-- Definizione chiavi esterne con eliminazione automatica                                            
ALTER TABLE COMMNOMIN ADD CONSTRAINT FK_NOMIN_ALBO FOREIGN KEY ( IDALBO ) REFERENCES COMMALBO( ID ) ON DELETE CASCADE;
ALTER TABLE COMMRUOLI ADD CONSTRAINT FK_RUOLI_NOMIN FOREIGN KEY ( IDNOMIN ) REFERENCES COMMNOMIN( ID ) ON DELETE CASCADE;

ALTER TABLE MECATALOGO ADD CONSTRAINT FK_MECATALOGO_GAREALBO FOREIGN KEY ( CODGAR,NGARA ) REFERENCES GAREALBO( CODGAR,NGARA ) ON DELETE CASCADE;

ALTER TABLE MEARTCAT ADD CONSTRAINT UN_MEARTCAT_COD UNIQUE (NGARA,COD);
ALTER TABLE MEARTCAT ADD CONSTRAINT FK_MEARTCAT_OPES FOREIGN KEY ( NGARA,NOPEGA ) REFERENCES OPES( NGARA3,NOPEGA ) ON DELETE CASCADE;

ALTER TABLE MEALLARTCAT ADD CONSTRAINT FK_MEALLARTCAT_ARTCAT FOREIGN KEY ( IDARTCAT ) REFERENCES MEARTCAT( ID ) ON DELETE CASCADE;
ALTER TABLE MEALLARTCAT ADD CONSTRAINT UN_MEALLARTCAT UNIQUE (IDARTCAT,IDPRG,IDDOCDIG);

ALTER TABLE MEISCRIZPROD ADD CONSTRAINT FK_MEISCRIZPROD_DITG FOREIGN KEY ( CODGAR,CODIMP,NGARA ) REFERENCES DITG( CODGAR5,DITTAO,NGARA5 );
ALTER TABLE MEISCRIZPROD ADD CONSTRAINT FK_MEISCRIZPROD_ARTCAT FOREIGN KEY ( IDARTCAT ) REFERENCES MEARTCAT( ID );

ALTER TABLE MESTOISCRIZPROD ADD CONSTRAINT FK_MESTOISCRIZPROD_ISCRIZPROD FOREIGN KEY ( IDISCRIZPROD ) REFERENCES MEISCRIZPROD( ID ) ON DELETE CASCADE;

ALTER TABLE MEALLISCRIZPROD ADD CONSTRAINT FK_MEALLISCRIZPROD_ISCRIZPROD FOREIGN KEY ( IDISCRIZPROD ) REFERENCES MEISCRIZPROD( ID ) ON DELETE CASCADE;
ALTER TABLE MEALLISCRIZPROD ADD CONSTRAINT UN_MEALLISCRIZPROD UNIQUE (IDISCRIZPROD,IDPRG,IDDOCDIG);
ALTER TABLE MEALLPROD ADD CONSTRAINT FK_MEALLPROD_PROD FOREIGN KEY ( IDPROD ) REFERENCES MESTOISCRIZPROD( ID ) ON DELETE CASCADE;

ALTER TABLE MERICATT ADD CONSTRAINT FK_MERICATT_MERIC FOREIGN KEY ( IDRIC ) REFERENCES MERIC( ID ) ON DELETE CASCADE;
ALTER TABLE MERICART ADD CONSTRAINT FK_MERICART_MERIC FOREIGN KEY ( IDRIC ) REFERENCES MERIC( ID ) ON DELETE CASCADE;
ALTER TABLE MERICPROD ADD CONSTRAINT FK_MERICPROD_MERICART FOREIGN KEY ( IDRICART ) REFERENCES MERICART( ID ) ON DELETE CASCADE;

