-- Creazione TRIGGER ------------------------
---------------------------------------------
-- Cancellazione documenti allegati all'articolo del mercato elettronico
DROP TRIGGER IF EXISTS tr_meallartcat_before_del ON meallartcat CASCADE;

CREATE OR REPLACE FUNCTION delete_docallart() 
	RETURNS trigger AS 
$tr_meallartcat_before_del$
BEGIN
	DELETE FROM w_docdig WHERE idprg = OLD.idprg AND iddocdig = OLD.iddocdig;
	RETURN OLD;
END
$tr_meallartcat_before_del$ LANGUAGE plpgsql;

CREATE TRIGGER tr_meallartcat_before_del
	AFTER DELETE ON meallartcat
	FOR EACH ROW EXECUTE PROCEDURE delete_docallart();

-- Cancellazione delle occorrenze di gardoc_wsdm relazionate ai documenti associati
DROP TRIGGER IF EXISTS tr_gardoc_wsdm_before_del ON C0OGGASS CASCADE;

CREATE OR REPLACE FUNCTION delete_gardoc_wsdm() 
	RETURNS trigger AS 
$tr_gardoc_wsdm_before_del$
BEGIN
	DELETE FROM gardoc_wsdm WHERE provenienza = '4' and key1 = OLD.c0aprg AND key2 = OLD.c0acod;
	RETURN OLD;
END
$tr_gardoc_wsdm_before_del$ LANGUAGE plpgsql;

CREATE TRIGGER tr_gardoc_wsdm_before_del
	AFTER DELETE ON C0OGGASS
	FOR EACH ROW EXECUTE PROCEDURE delete_gardoc_wsdm();

-------------------------------------------------
-- View per import dati da altro db -------------
-- Solo in inizializzazione struttura perchè poi deve essere personalizzata prezzo il cliente
-------------------------------------------------
-- (S.Santi 08.01.2015) View utilizzata per importare in gare dati da altro db (richiesta di Quadrifoglio).
-- La view va ridefinita in base alle specifiche del cliente rispettando la tipologia dei campi come indicato sotto.
--
create view v_gare_datiesterni as
	select cast('' as varchar(1)) codcig,
	  cast('' as varchar(1)) prefcod,
	  0 tipgen,
	  cast('' as varchar(1)) cenint,
	  cast('' as varchar(1)) oggetto,
	  0 tipgarg,
	  0 impapp,
	  cast('' as varchar(1)) nomest,
	  cast('' as varchar(1)) cfimp,
	  cast('' as varchar(1)) cfest,
	  0 nazimp,
	  0 iaggiu,
	  to_date('01/01/1900','DD/MM/YYYY') dattoa,
	  to_date('01/01/1900','DD/MM/YYYY') dverbc,
	  to_date('01/01/1900','DD/MM/YYYY') dcertu,
	  0 impliq
	  from gare where 1 <> 1;

-------------------------------------------------
-- (20.02.2020) View per sezione 'Consulenti e collaboratori' su portale 
-- Da personalizzare presso il cliente per gestire eventuali dati pregressi
-- (18.05.2022) Aggiunto colonne codsa e descsa
-------------------------------------------------
create or replace view v_consulenti_custom as
	select
		cast(null as text) codgar,
		cast(null as text) ngara,
		cast(null as text) codice,
		cast(null as text) codicesoggetto,
		cast(null as text) soggettopercettore,
		cast(null as text) protocollo,
		cast(null as timestamp) as data,
		cast(null as text) ragioneincarico,
		cast(null as text) oggprest,
		cast(null as numeric(24,5)) compensoprevisto,
		cast(null as text) partevariabile,
		cast(null as timestamp) inizio,
		cast(null as timestamp)fine,
		cast(null as text) procedura,
		cast(null as INT) numpart,
		cast(null as text) codsa,
		cast(null as text) descsa
	from gare
	where 1=0;

