-- View per elenchi e cataloghi -----------------
-------------------------------------------------
-- (E.C. - 17/11/2011) Elenco delle gare per albi fornitori
--
create or replace view v_gare_eleditte (codgar, codice, tipoele, periodo, oggetto, isarchi, genere) as 
   select gare.codgar1, gare.ngara, tab1.tab1desc, garealbo.periodo, garealbo.oggetto, garealbo.isarchi, gare.genere 
	from gare, garealbo, tab1 
	where garealbo.codgar=gare.codgar1 and garealbo.ngara=gare.ngara and gare.codgar1 like '$%' 
	and gare.genere=10 and to_number(garealbo.tipoele,'999999999')=tab1.tab1tip and tab1.tab1cod='A1071';

-- Elenco delle gare per cataloghi
--
create or replace view v_gare_catalditte (codgar, codice, tipoele, periodo, oggetto, isarchi, genere, cenint) as 
	select gare.codgar1, 
		   gare.ngara, 
		   tab1.tab1desc, 
		   garealbo.periodo, 
		   garealbo.oggetto, 
		   garealbo.isarchi, 
		   gare.genere,
		   torn.cenint
	from torn inner join gare on gare.codgar1=torn.codgar
			  inner join garealbo on garealbo.codgar=gare.codgar1 and garealbo.ngara=gare.ngara
			  inner join tab1 on to_number(garealbo.tipoele,'999999999')=tab1.tab1tip and tab1.tab1cod='A1071'
	where gare.genere=20 
	and gare.codgar1 like '$%';
	
-- (S.Santi 09.08.12) Lista delle categorie per cui la ditta risulta iscritta in elenchi operatori validi
-- Considera gli elenchi in corso di validità
-- Considera la classifica massima per cui la ditta è iscritta
-- (S.Santi 04.12.12) Adeguamento per gestione categorie con struttura gerarchica: aggiunto le colonne ISFOGLIA e NUMLIV
--
create or replace view v_cate_elenchi as
	select i.codimp,
		 i.codcat,
		 c.descat,
		 c.tiplavg tipcat,
		 i.numcla,
		 case
			when c.tiplavg=1 then t1.tab1desc
			when c.tiplavg=2 then t2.tab1desc
			when c.tiplavg=3 then t3.tab1desc
			when c.tiplavg=4 then t4.tab1desc
			else t5.tab1desc
		 end descla,
		 c.titcat,
		 c.isfoglia,
		 c.numliv,
		 c.numord
	from v_cais_tit c, 
	(select iscrizcat.codimp,
		iscrizcat.codcat,
		case when max(supnumclass) is null then max(infnumclass) else max(supnumclass) end numcla
	from iscrizcat, garealbo
	where iscrizcat.ngara=garealbo.ngara
	and (garealbo.dtermval is null or to_date(to_char(garealbo.dtermval,'YYYY/MM/DD') || ' ' || '23:59:59', 'YYYY/MM/DD HH24:MI:SS')>=now())
	and iscrizcat.codcat <>'0'
	group by codimp,codcat) i
	left outer join tab1 t1 on (t1.tab1cod='A1015' and t1.tab1tip=i.numcla)
	left outer join tab1 t2 on (t2.tab1cod='G_035' and t2.tab1tip=i.numcla)
	left outer join tab1 t3 on (t3.tab1cod='G_036' and t3.tab1tip=i.numcla)
	left outer join tab1 t4 on (t4.tab1cod='G_037' and t4.tab1tip=i.numcla)
	left outer join tab1 t5 on (t5.tab1cod='G_049' and t5.tab1tip=i.numcla)
	where i.codcat=c.caisim;

-- (S.Santi 04.11.11) Estensione della view V_CAIS_TIT per permettere la visualizzazione nella lista 
-- delle categorie d'iscrizione dell'operatore le categorie con codice 0
-- (S.Santi 30.01.12) Aggiunto descrizione della classifica, recuperata dal tabellato relativo alla tipologia della categoria
-- (S.Santi 25.10.12) Aggiunto descrizione della classifica per la tipologia 'Servizi professionali' (TIPLAVG=5)
-- (S.Santi 29.11.12) Nel caso di struttura gerarchica delle cateogrie d''iscrizione, 
--					   vengono elencate anche le categorie figlie della prevalente e ulteriori della gara
-- (S.Santi 26.09.14) Forzato il cast del campo ISPREV per evitare malfunzionamento con il compositore
--
create or replace view v_gare_categorie as 
	select ngara, (cast('1' as varchar(1))) isprev, ncatg, caisim catiga, descat, tiplavg, titcat, impiga, impbasg, numcla,
	 case when tiplavg=1 then (select tab1desc from tab1 where tab1cod='A1015' and tab1tip=numcla)
				when tiplavg=2 then (select tab1desc from tab1 where tab1cod='G_035' and tab1tip=numcla) 
				when tiplavg=3 then (select tab1desc from tab1 where tab1cod='G_036' and tab1tip=numcla)
				when tiplavg=4 then (select tab1desc from tab1 where tab1cod='G_037' and tab1tip=numcla) 
				else (select tab1desc from tab1 where tab1cod='G_049' and tab1tip=numcla) end descla,
	 '' quaobb, '' acontec, '' ultnote,
	 isfoglia, numliv, numord, 
	 case when catiga=caisim then '1' else '0' end iscatgara
	from catg, v_cais_tit
	where (catg.catiga=v_cais_tit.caisim or catg.catiga=v_cais_tit.codliv1 or catg.catiga=v_cais_tit.codliv2 
		or catg.catiga=v_cais_tit.codliv3 or catg.catiga=v_cais_tit.codliv4)
	union all
	select ngara3, (cast('2' as varchar(1))) isprev, nopega, caisim, descat, tiplavg, titcat, iscoff, impapo, numclu, 
	 case when tiplavg=1 then (select tab1desc from tab1 where tab1cod='A1015' and tab1tip=numclu)
		when tiplavg=2 then (select tab1desc from tab1 where tab1cod='G_035' and tab1tip=numclu) 
		when tiplavg=3 then (select tab1desc from tab1 where tab1cod='G_036' and tab1tip=numclu)
		when tiplavg=4 then (select tab1desc from tab1 where tab1cod='G_037' and tab1tip=numclu) 
		else (select tab1desc from tab1 where tab1cod='G_049' and tab1tip=numclu) end descla,
	 opes.quaobb, opes.acontec, descop,
	 isfoglia, numliv, numord, 
	 case when catoff=caisim then '1' else '0' end iscatgara
	from opes, v_cais_tit
	where (opes.catoff=v_cais_tit.caisim or opes.catoff=v_cais_tit.codliv1 or opes.catoff=v_cais_tit.codliv2 
		or opes.catoff=v_cais_tit.codliv3 or opes.catoff=v_cais_tit.codliv4);
		
-- (S.Santi 18.09.18) 
-- Estensione della view V_GARE_TORN per permettere la visualizzazione nel profilo di ricerca
-- (S.Santi 19.09.2019) Modificato join su profiloweb per gestire il caso in cui i profili hanno prefisso del tipo '$001$' anziche' '$1$'
-- (S.Santi 18.12.2020) Aggiunto avvisi
-- (M.C. 23.03.2022) Aggiunto campo isavviso che indica se si è in presenza di un avviso
--		
create or replace view V_GARE_PROFILO as
       select v_gare_torn.codice, v_gare_torn.codgar, v_gare_torn.oggetto,v_gare_torn.codcig,torn.cenint, v_gare_torn.profiloweb,
                v_gare_torn.genere, v_gare_torn.tipgar, v_gare_torn.isarchi,
                case when tab2.tab2d1 ='default' then 'PG_GARE' else tab2.tab2d1 end as codprofilo, '2' isavviso
                from v_gare_torn inner join torn on (v_gare_torn.codgar=torn.codgar and torn.profiloweb is null)
                INNER JOIN TAB2 ON (TAB2COD='A1z03' AND ',' || TAB2.TAB2D2 || ',' LIKE '%,' || CAST(V_GARE_TORN.TIPGAR AS VARCHAR(4)) || ',%' AND TAB2D1 not like '$%')
       union all
       select v_gare_torn.codice, v_gare_torn.codgar, v_gare_torn.oggetto,v_gare_torn.codcig,torn.cenint, v_gare_torn.profiloweb,
                v_gare_torn.genere, v_gare_torn.tipgar, v_gare_torn.isarchi,
                tab2.tab2d1 as codprofilo, '2' isavviso
                from v_gare_torn inner join torn on (v_gare_torn.codgar=torn.codgar and torn.profiloweb is not null)
                INNER JOIN TAB2 ON TAB2COD='A1z03' and tab2d1 like '$%' AND torn.profiloweb = to_number(substring(substring(tab2d1,2,100),1,position('$' in substring(tab2d1,2,100))-1),'99999')
       union all
       select gareavvisi.ngara codice,gareavvisi.codgar,gareavvisi.oggetto,cast(null as text) codcig,torn.cenint,cast(null as numeric(3,0)) profiloweb,
                11,cast(null as numeric(7,0)) tipgar,gareavvisi.isarchi, tab1.tab1desc, '1' isavviso 
                from gareavvisi inner join torn on (gareavvisi.codgar=torn.codgar)
                inner join gare on (gareavvisi.ngara=gare.ngara)
                inner join tab1 on (tab1cod='A1167' and tab1desc is not null)
				WHERE gareavvisi.tipogen is null;
  
		
-- (S.Santi 04.11.11) 
-- Estensione della view V_CAIS_TIT per permettere la visualizzazione nella lista 
-- delle categorie d'iscrizione dell'operatore le categorie con codice 0
-- (S.Santi 31.10.12) Adeguamento per gestione categorie con struttura gerarchcia: aggiunto le colonne ISFOGLIA e NUMLIV
--
create or replace view v_iscrizcat_tit as 
	select caisim,descat,tiplavg,titnord, titcat,caisord,quaobb,acontec,isfoglia,numliv,numord from v_cais_tit
	union all 
	select '0','Gare per '||TAB1DESC,TAB1TIP,0,'-1',null,'','','1',1,'9'||cast (tab1tip as text)||'0000000000*****' 
	from v_cais_tit,tab1 where caisim='OG1' and tab1cod='A1007';

-- (S.Santi 11.01.12) Lista delle categorie per cui la ditta è iscritta all''elenco con il dettaglio delle classi
-- (S.Santi 31.10.12) Adeguamento per gestione categorie con struttura gerarchcia: aggiunto le colonne ISFOGLIA e NUMLIV
-- (S.Santi 06.05.16) Aggiunto campi numero classifica specifici per tipologia, tabellati nel cocampi, da utilizzare nei report avanzati
-- (S.Santi 26.03.18) Aggiunto campo 'N.aggiudicazioni'
--
create or replace view v_iscrizcat_classi as
	select v_iscrizcat_tit.caisim, v_iscrizcat_tit.descat, v_iscrizcat_tit.descat descat1,
				v_iscrizcat_tit.tiplavg, v_iscrizcat_tit.titnord, v_iscrizcat_tit.titcat,
				v_iscrizcat_tit.caisord, v_iscrizcat_tit.quaobb, v_iscrizcat_tit.acontec, 
				v_iscrizcat_tit.isfoglia, v_iscrizcat_tit.numliv, v_iscrizcat_tit.numord, 
				-100 numclass, iscrizcat.infnumclass, iscrizcat.supnumclass, 
				null numclass_l, case when tiplavg=1 then iscrizcat.infnumclass else null end infnumcla_l, case when tiplavg=1 then iscrizcat.supnumclass else null end supnumcla_l, 
				null numclass_f, case when tiplavg=2 then iscrizcat.infnumclass else null end infnumcla_f, case when tiplavg=2 then iscrizcat.supnumclass else null end supnumcla_f, 
				null numclass_s, case when tiplavg=3 then iscrizcat.infnumclass else null end infnumcla_s, case when tiplavg=3 then iscrizcat.supnumclass else null end supnumcla_s, 
				null numclass_l15, case when tiplavg=4 then iscrizcat.infnumclass else null end infnumcla_l15, case when tiplavg=4 then iscrizcat.supnumclass else null end supnumcla_l15, 
				null numclass_sp, case when tiplavg=5 then iscrizcat.infnumclass else null end infnumcla_sp, case when tiplavg=5 then iscrizcat.supnumclass else null end supnumcla_sp, 
				iscrizcat.invrea, iscrizcat.invpen, iscrizcat.altpen, iscrizcat.notpen, iscrizcat.ultnot, iscrizcat.aggrea,
				iscrizcat.codgar, iscrizcat.ngara, iscrizcat.codimp
		from v_iscrizcat_tit,iscrizcat 
		where v_iscrizcat_tit.caisim = iscrizcat.codcat and v_iscrizcat_tit.tiplavg = iscrizcat.tipcat
	union all
	select v_iscrizcat_tit.caisim,
			'Classifica: '|| 
				case when tiplavg=1 then (select tab1desc from tab1 where tab1cod='A1015' and tab1tip=numclass) 
					when tiplavg=2 then (select tab1desc from tab1 where tab1cod='G_035' and tab1tip=numclass) 
					when tiplavg=3 then (select tab1desc from tab1 where tab1cod='G_036' and tab1tip=numclass) 
					when tiplavg=4 then (select tab1desc from tab1 where tab1cod='G_037' and tab1tip=numclass) 
					else (select tab1desc from tab1 where tab1cod='G_049' and tab1tip=numclass) end,
			v_iscrizcat_tit.descat,v_iscrizcat_tit.tiplavg, v_iscrizcat_tit.titnord, v_iscrizcat_tit.titcat, 
			v_iscrizcat_tit.caisord, null,null,
			v_iscrizcat_tit.isfoglia, v_iscrizcat_tit.numliv, v_iscrizcat_tit.numord, 
			iscrizclassi.numclass,null,null,
			case when tiplavg=1 then iscrizclassi.numclass else null end numclass_l, null,null,
			case when tiplavg=2 then iscrizclassi.numclass else null end numclass_f, null,null,
			case when tiplavg=3 then iscrizclassi.numclass else null end numclass_s, null,null,
			case when tiplavg=4 then iscrizclassi.numclass else null end numclass_l150, null,null,
			case when tiplavg=5 then iscrizclassi.numclass else null end numclass_sp, null,null,
			iscrizclassi.invrea, iscrizclassi.invpen, iscrizclassi.altpen, iscrizclassi.notpen, iscrizclassi.ultnot, iscrizclassi.aggrea,
			iscrizcat.codgar, iscrizcat.ngara, iscrizcat.codimp
		from v_iscrizcat_tit,iscrizcat,iscrizclassi
		where v_iscrizcat_tit.caisim = iscrizcat.codcat and v_iscrizcat_tit.tiplavg = iscrizcat.tipcat
			and iscrizcat.ngara=iscrizclassi.ngara and iscrizcat.codimp=iscrizclassi.codimp 
			and iscrizcat.codcat=iscrizclassi.codcat and iscrizcat.tipcat=iscrizclassi.tipcat;

-- (E.C. - 17/11/2011) Ditte iscritte all''albo fornitori con somma
-- (S.Santi 26.09.11) Aggiunto filtro su Numero ordine. Aggiunti i campi Numero inviti e Numero penalità in analogia a V_DITTE_ELECAT
-- (S.Santi 16.10.12) Tolto raggruppamento sulla tipologia (TIPCAT.ISCRIZCAT)
-- (S.Santi 02.11.12) Aggiunto colonna NUMIP per conteggio inviti e penalità senza inviti virtuali
-- (S.Santi 03.07.2014) Esteso selezione ditte sui cataloghi. Tolto istruzione Drop view
-- (S.Santi 10.01.2017) Aggiunto campi relativi a località ditta (LOCIMP, PROIMP.IMPR)
-- (M.C. 04/10/2017) Aggiunto campo IAGGIUELE.DITG
-- (S.Santi 19.03.2018) Adeguamento per nuovi criteri di rotazione su numero aggiudicazioni
--
create or replace view v_ditte_elesum as 
select gare.ngara gara, ditg.dittao codice, ditg.nomimo ragsoc, impr.locimp, impr.proimp, ditg.numordpl numord, ditg.iaggiuele,
	sum(case when (iscrizcat.invrea is null) then 0 else iscrizcat.invrea end) numinv, 
	sum(case when (iscrizcat.invpen is null) then 0 else iscrizcat.invpen end) numpen,
	sum(case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end) numalt,
	sum((case when (iscrizcat.invrea is null) then 0 else iscrizcat.invrea end) + 
		(case when (iscrizcat.invpen is null) then 0 else iscrizcat.invpen end) + 
		(case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end)) numir,
	sum((case when (iscrizcat.invrea is null) then 0 else iscrizcat.invrea end) + 
		(case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end)) numip,
	sum(case when (iscrizcat.aggrea is null) then 0 else iscrizcat.aggrea end) numagg, 
	sum((case when (iscrizcat.aggrea is null) then 0 else iscrizcat.aggrea end) + 
		(case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end)) numap
from ditg
inner join impr on ditg.dittao=impr.codimp
inner join iscrizcat on ditg.codgar5=iscrizcat.codgar and ditg.ngara5=iscrizcat.ngara and ditg.dittao=iscrizcat.codimp 
inner join gare on ditg.codgar5=gare.codgar1 and ditg.ngara5=gare.ngara
where gare.genere in (10,20)
	and ditg.abilitaz=1 and (ditg.dabilitaz is not null) and ditg.numordpl is not null
group by gare.ngara, ditg.dittao, ditg.nomimo, impr.locimp, impr.proimp, ditg.numordpl, ditg.iaggiuele;

-- (E.C. - 17/11/2011) Ditte iscritte all'albo fornitori e abilitate all'inserimento in gara 
-- (S.Santi 26.09.11) Aggiunto filtro su Numero ordine
-- (S.Santi 10.01.12) Aggiunto dettaglio inviti e penalità sulle classi della categoria
-- (S.Santi 02.11.12) Aggiunto colonna NUMIP per conteggio inviti e penalità senza inviti virtuali e 
--  nuove colonne con numero inviti e penalità totali (NUMINVTOT, ..., NUMIPTOT) per gestione rotazione su inviti complessivi dell''elenco
-- (S.Santi 03.07.2014) Esteso selezione ditte sui cataloghi. Tolto istruzione Drop view
-- (S.Santi 10.01.2017) Aggiunto campi relativi a località ditta (LOCIMP, PROIMP.IMPR) e ottimizzato view
-- (M.C. 04/10/2017) Aggiunto campo IAGGIUELE.DITG
-- (S.Santi 19.03.2018) Adeguamento per nuovi criteri di rotazione su numero aggiudicazioni
-- (S.Santi 22.01.2021) Sostituito CTE con view per risolvere pb di saturazione tablespace TEMP, riscontrato su DB Oracle
-- (M.C. 14/06/2022) Aggiunto campo TIPCAT.ISCRIZCAT
--
create or replace view v_ditte_elecat_totali as
  select iscrizcat.codgar, iscrizcat.ngara, iscrizcat.codimp, 
		 sum(case when (iscrizcat.invrea is null) then 0 else iscrizcat.invrea end) numinv, 
		 sum(case when (iscrizcat.invpen is null) then 0 else iscrizcat.invpen end) numpen,
		 sum(case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end) numalt,
		 sum((case when (iscrizcat.invrea is null) then 0 else iscrizcat.invrea end) + 
			(case when (iscrizcat.invpen is null) then 0 else iscrizcat.invpen end) + 
			(case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end)) numir,
		 sum((case when (iscrizcat.invrea is null) then 0 else iscrizcat.invrea end) + 
			(case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end)) numip,
		 sum(case when (iscrizcat.aggrea is null) then 0 else iscrizcat.aggrea end) numagg, 
		 sum((case when (iscrizcat.aggrea is null) then 0 else iscrizcat.aggrea end) + 
			(case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end)) numap
	from iscrizcat
	group by codgar, ngara, codimp;
--
create or replace view v_ditte_elecat as
   select gare.ngara gara, ditg.dittao codice, ditg.nomimo ragsoc, impr.locimp, impr.proimp, ditg.numordpl numord, ditg.iaggiuele,
		  (case when (iscrizcat.invrea is null) then 0 else iscrizcat.invrea end) numinv,
		  (case when (iscrizcat.invpen is null) then 0 else iscrizcat.invpen end) numpen, 
		  (case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end) numalt, 
		  (case when (iscrizcat.invrea is null) then 0 else iscrizcat.invrea end) + 
		  (case when (iscrizcat.invpen is null) then 0 else iscrizcat.invpen end) + 
		  (case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end) numir,
		  (case when (iscrizcat.invrea is null) then 0 else iscrizcat.invrea end) + 
		  (case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end) numip,
		  (case when (iscrizcat.aggrea is null) then 0 else iscrizcat.aggrea end) numagg,
		  (case when (iscrizcat.aggrea is null) then 0 else iscrizcat.aggrea end) + 
		  (case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end) numap,
		  iscrizcat.codcat, iscrizcat.tipcat, iscrizcat.infnumclass, iscrizcat.supnumclass,
		  iscrizclassi.numclass,
		  (case when (iscrizclassi.invrea is null) then 0 else iscrizclassi.invrea end) numinvcla,
		  (case when (iscrizclassi.invpen is null) then 0 else iscrizclassi.invpen end) numpencla, 
		  (case when (iscrizclassi.altpen is null) then 0 else iscrizclassi.altpen end) numaltcla, 
		  (case when (iscrizclassi.invrea is null) then 0 else iscrizclassi.invrea end) + 
		  (case when (iscrizclassi.invpen is null) then 0 else iscrizclassi.invpen end) +
		  (case when (iscrizclassi.altpen is null) then 0 else iscrizclassi.altpen end) numircla,
		  (case when (iscrizclassi.invrea is null) then 0 else iscrizclassi.invrea end) + 
		  (case when (iscrizclassi.altpen is null) then 0 else iscrizclassi.altpen end) numipcla,
		  (case when (iscrizclassi.aggrea is null) then 0 else iscrizclassi.aggrea end) numaggcla,
		  (case when (iscrizclassi.aggrea is null) then 0 else iscrizclassi.aggrea end) + 
		  (case when (iscrizclassi.altpen is null) then 0 else iscrizclassi.altpen end) numapcla,
		  totali.numinv numinvtot, totali.numpen numpentot, totali.numalt numalttot,
		  totali.numir numirtot, totali.numip numiptot,
		  totali.numagg numaggtot, totali.numap numaptot
	from ditg inner join gare on (ditg.codgar5=gare.codgar1 and ditg.ngara5=gare.ngara)
		inner join impr on (ditg.dittao=impr.codimp)
		inner join iscrizcat on (ditg.codgar5=iscrizcat.codgar and ditg.ngara5=iscrizcat.ngara and ditg.dittao=iscrizcat.codimp)
		inner join v_ditte_elecat_totali totali on (ditg.codgar5=totali.codgar and ditg.ngara5=totali.ngara and ditg.dittao=totali.codimp)
		left outer join iscrizclassi on (iscrizcat.codgar=iscrizclassi.codgar and iscrizcat.ngara=iscrizclassi.ngara 
			and iscrizcat.codimp=iscrizclassi.codimp and iscrizcat.codcat=iscrizclassi.codcat and iscrizcat.tipcat=iscrizclassi.tipcat)
	where gare.codgar1 like '$%' and gare.genere in (10,20) 
	   and ditg.abilitaz=1 and (ditg.dabilitaz is not null) and ditg.numordpl is not null;

-- (S.Santi 08.03.2017) Nuova view per selezione da elenco mediante rotazione per stazione appaltante
-- (M.C. 04/10/2017) Aggiunto campo IAGGIUELE.DITG
-- (S.Santi 19.03.2018) Adeguamento per nuovi criteri di rotazione su numero aggiudicazioni
-- (S.Santi 22.01.2021) Sostituito CTE con view per risolvere pb di saturazione tablespace TEMP, riscontrato su DB Oracle
--
create or replace view v_ditte_elecat_sa_totpen as
	select iscrizcat.codgar, iscrizcat.ngara, iscrizcat.codimp, 
		 sum(case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end) numalt
	from iscrizcat
	group by codgar, ngara, codimp;
--
create or replace view v_ditte_elecat_sa_totsa as
	select iscrizuff.cenint, iscrizuff.codgar, iscrizuff.ngara, iscrizuff.codimp, 
		 sum(case when (iscrizuff.invrea is null) then 0 else iscrizuff.invrea end) numinv, 
		 sum(case when (iscrizuff.invpen is null) then 0 else iscrizuff.invpen end) numpen,
		 sum((case when (iscrizuff.invrea is null) then 0 else iscrizuff.invrea end) + 
			(case when (iscrizuff.invpen is null) then 0 else iscrizuff.invpen end)) numirnoalt,
		 sum(case when (iscrizuff.aggrea is null) then 0 else iscrizuff.aggrea end) numagg 
	from iscrizuff 
	group by iscrizuff.cenint, iscrizuff.codgar, iscrizuff.ngara, iscrizuff.codimp;
--
create or replace view v_ditte_elecat_sa as
	select gare.ngara gara, ditg.dittao codice, ditg.nomimo ragsoc, impr.locimp, impr.proimp, ditg.numordpl numord, ditg.iaggiuele,
			  (case when (iscrizuff.invrea is null) then 0 else iscrizuff.invrea end) numinv,
			  (case when (iscrizuff.invpen is null) then 0 else iscrizuff.invpen end) numpen, 
			  (case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end) numalt, 
			  (case when (iscrizuff.invrea is null) then 0 else iscrizuff.invrea end) + 
			  (case when (iscrizuff.invpen is null) then 0 else iscrizuff.invpen end) + 
			  (case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end) numir,
			  (case when (iscrizuff.invrea is null) then 0 else iscrizuff.invrea end) + 
			  (case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end) numip,
			  (case when (iscrizuff.aggrea is null) then 0 else iscrizuff.aggrea end) numagg,
			  (case when (iscrizuff.aggrea is null) then 0 else iscrizuff.aggrea end) + 
			  (case when (iscrizcat.altpen is null) then 0 else iscrizcat.altpen end) numap,
			  uffint.codein cenint, iscrizcat.codcat, iscrizcat.tipcat, iscrizcat.infnumclass, iscrizcat.supnumclass,
			  iscrizclassi.numclass,
			  (case when (totali_sa.numinv is null) then 0 else totali_sa.numinv end) numinvtot,
			  (case when (totali_sa.numpen is null) then 0 else totali_sa.numpen end) numpentot,
			  totali_altpen.numalt numalttot,
			  (case when (totali_sa.numirnoalt is null) then totali_altpen.numalt else totali_sa.numirnoalt + totali_altpen.numalt end) numirtot,
			  (case when (totali_sa.numinv is null) then totali_altpen.numalt else totali_sa.numinv + totali_altpen.numalt end) numiptot,
			  (case when (totali_sa.numagg is null) then 0 else totali_sa.numagg end) numaggtot,
			  (case when (totali_sa.numagg is null) then totali_altpen.numalt else totali_sa.numagg + totali_altpen.numalt end) numaptot			  
		from ditg inner join gare on (ditg.codgar5=gare.codgar1 and ditg.ngara5=gare.ngara)
			inner join impr on (ditg.dittao=impr.codimp)
			inner join iscrizcat on (ditg.codgar5=iscrizcat.codgar and ditg.ngara5=iscrizcat.ngara and ditg.dittao=iscrizcat.codimp)
			inner join uffint on (1=1)
			left outer join iscrizuff on (uffint.codein=iscrizuff.cenint and iscrizuff.codgar=iscrizcat.codgar and iscrizuff.ngara=iscrizcat.ngara 
							and iscrizuff.codimp=iscrizcat.codimp and iscrizuff.codcat=iscrizcat.codcat and iscrizuff.tipcat=iscrizcat.tipcat)
			left outer join v_ditte_elecat_sa_totsa totali_sa on (uffint.codein=totali_sa.cenint and ditg.codgar5=totali_sa.codgar and ditg.ngara5=totali_sa.ngara and ditg.dittao=totali_sa.codimp)
			inner join v_ditte_elecat_sa_totpen totali_altpen on (ditg.codgar5=totali_altpen.codgar and ditg.ngara5=totali_altpen.ngara and ditg.dittao=totali_altpen.codimp)
			left outer join iscrizclassi on (iscrizcat.codgar=iscrizclassi.codgar and iscrizcat.ngara=iscrizclassi.ngara 
				and iscrizcat.codimp=iscrizclassi.codimp and iscrizcat.codcat=iscrizclassi.codcat and iscrizcat.tipcat=iscrizclassi.tipcat)
		where gare.codgar1 like '$%' and gare.genere in (10,20) 
		   and ditg.abilitaz=1 and (ditg.dabilitaz is not null) and ditg.numordpl is not null;

-------------------------------------------------
-- View Mercato elettronico ---------------------
-------------------------------------------------
create or replace view v_meprodotti as (select * from mestoiscrizprod);
create or replace view v_meallprodotti as (select * from meallprod);
create or replace view v_sel_meprodotti as (select * from mestoiscrizprod where datfin is null);

-- (S.Santi 30.04.2014) Elenco dei prodotti inseriti in catalogo
-- (S.Santi 17.09.2014) Sostituito utilizzo MEISCRIZPROD con MESTOISCRIZPROD (entità storico prodotti) e aggiunti campi 
-- per gestione lista prodotti associati a un articolo
-- 
create or replace view v_cataprod as
	select meartcat.ngara,meartcat.id idarticolo,cais.caisim,cais.descat,meartcat.descr, meartcat.cod,meartcat.tipo,
	mestoiscrizprod.idiscrizprod idprodotto,mestoiscrizprod.codimp,
	mestoiscrizprod.nome,mestoiscrizprod.codoe,mestoiscrizprod.descagg,mestoiscrizprod.stato,mestoiscrizprod.datini datmod,
	mestoiscrizprod.tempocons,mestoiscrizprod.przunitprod,mestoiscrizprod.perciva,mestoiscrizprod.datscadoff,
	mestoiscrizprod.id idprodstorico,impr.nomest
	from mestoiscrizprod,meartcat,opes,cais,impr
	where mestoiscrizprod.datfin is null and mestoiscrizprod.idartcat=meartcat.id 
	and meartcat.ngara = opes.ngara3 and meartcat.nopega = opes.nopega and opes.catoff=cais.caisim
	and mestoiscrizprod.codimp=impr.codimp;

-- (S.Santi 04.06.2014) Lista degli ordini di acquisto della ricerca di mercato.
--   Vengono considerati sia gli ordini generati (occ. in GARE con GENERE=4),
--   sia gli ordini non ancora generati (considera i prodotti selezionati 
--   in fase di valutazione relativi a articoli non ancora associati a un ordine di acquisto)
--
create or replace view v_oda as
	select mericart.idric idric,
		'' ngara,
		null numoda,
		'' oggetto,
		1 stato,
		impr.codimp ditta,
		impr.nomest nomest,
		sum(mericprod.preoff) iaggiu,
		0 impiva,
		0 imptot,
		count(mericprod.idricart) numprod
	from mericart,mericprod,impr
	where mericart.id=mericprod.idricart
		and impr.codimp=mericprod.codimp
		and mericart.ngara is null
		and mericprod.acquista='1'
		group by impr.codimp,impr.nomest,mericart.idric
	union
	select gare.idric idric,
		gare.ngara,
		gare.nrepat numoda,
		gare.not_gar oggetto,
		garecont.stato,
		impr.codimp ditta,
		impr.nomest nomest,
		gare.iaggiu,
		garecont.impiva,
		garecont.imptot,
		(select count(*) from mericprod,mericart where mericprod.idricart=mericart.id and mericart.ngara=gare.ngara and mericprod.acquista='1') numprod
	from gare,garecont,impr
	where gare.ngara=garecont.ngara and garecont.ncont=1
	    and impr.codimp=gare.ditta
		and gare.genere=4 and gare.idric is not null;

-- (S.Santi 09.06.2014) Lista dei prodotti degli ordini di acquisto.
--  Se ordine già generato, i prodotti hanno il campo NGARA valorizzato con il codice dell''ordine.
--  Se ordine non ancora generato, i prodotti hanno il campo NGARA nullo e vanno filtrati sul codice impresa.
--
create or replace view v_odaprod as
	select mericart.idric,
		mericprod.idricart,
		mericart.ngara,
		mericprod.codimp,
		mericprod.idprod,
		mericart.idartcat,
		mestoiscrizprod.codoe,
		mestoiscrizprod.nome,
		meartcat.unimisacq,
		mestoiscrizprod.przunitprod,
		mericart.quanti quantiric,
		mericprod.quanti quantioff,
		mericprod.preoff,
		mericprod.perciva,
		mestoiscrizprod.tempocons,
		mestoiscrizprod.datscadoff,
		trim(to_char(mestoiscrizprod.tempocons,'99999'))||' '||tab1.tab1desc tempoconsegna,
		meartcat.przunitper,
		mericart.desdet1,mericart.quadet1,
		mericart.desdet2,mericart.quadet2
	from mericprod,mericart,mestoiscrizprod,meartcat,tab1
	where mericprod.idricart=mericart.id
		and mericprod.idprod=mestoiscrizprod.id
		and meartcat.id=mericart.idartcat
		and mericprod.acquista='1'
		and tab1.tab1cod='ME004' and tab1.tab1tip=meartcat.unimistempocons;

--------------------------------------------------------------------------------------
-- View Scadenzario su GARE e TORN per bandi di gara (Sabbadin 17.05.13) -------------
--------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW v_scad_bandi_pubb AS
	/* Pubblicazione avviso su profilo committente */
	SELECT g.codgar, 'PG-PUBAVVPROFCOMMITT' AS codevento, MIN(p.DATPUB) AS dataconsuntivo 
	  FROM v_gare_torn g INNER JOIN pubbli p ON g.codgar=p.codgar9 
	 WHERE g.genere IN (1,2,3) AND p.tippub=8
	GROUP BY g.codgar
	UNION ALL
	/* Pubblicazione avviso su quotidiani nazionali e locali */
	SELECT g.codgar, 'PG-PUBAVVQUOTNAZLOC' AS codevento, MIN(p.DATPUB) AS dataconsuntivo 
	  FROM v_gare_torn g INNER JOIN pubbli p ON g.codgar=p.codgar9 
	 WHERE g.genere IN (1,2,3) AND p.tippub IN (6,7)
	GROUP BY g.codgar
	UNION ALL
	/* Pubblicazione sulla GUUE e invio alla GURI */
	SELECT codgar, 'PG-PUBGUUEINVGURI' AS codevento, 
		   CASE WHEN datpubguue IS NULL THEN NULL 
		   ELSE 
			 CASE WHEN datinvguri IS NULL THEN NULL 
			 ELSE 
			   CASE WHEN datpubguue > datinvguri THEN datpubguue ELSE datinvguri END 
			 END 
		   END AS dataconsuntivo 
	  FROM (
			SELECT g.codgar, MIN(pguue.DATPUB) AS datpubguue, MIN(pguri.DINPUB) AS datinvguri
			  FROM v_gare_torn g LEFT OUTER JOIN pubbli pguue ON g.codgar=pguue.codgar9 LEFT OUTER JOIN pubbli pguri ON g.codgar=pguri.codgar9
			 WHERE g.genere IN (1,2,3) AND pguue.tippub=3 AND pguri.tippub=4
			GROUP BY g.codgar
		   ) A
	UNION ALL
	/* Pubblicazione su GURI */
	SELECT g.codgar, 'PG-PUBGURI' AS codevento, MIN(p.DATPUB) AS dataconsuntivo 
	  FROM v_gare_torn g INNER JOIN pubbli p ON g.codgar=p.codgar9 
	 WHERE g.genere IN (1,2,3) AND p.tippub=4
	GROUP BY g.codgar
	UNION ALL
	/* Pubblicazione su SITAT/ Min infrastrutture */
	SELECT g.codgar, 'PG-PUBSITATMININFRASTR' AS codevento, MIN(p.DATPUB) AS dataconsuntivo 
	  FROM v_gare_torn g INNER JOIN pubbli p ON g.codgar=p.codgar9 
	 WHERE g.genere IN (1,2,3) AND p.tippub IN (9,10)
	GROUP BY g.codgar
	UNION ALL
	/* Postinformazione su GUUE */
	SELECT g.codgar1 AS codgar, 'PG-POSTINFOGUUE' AS codevento, MIN(p.DINPUBG) AS dataconsuntivo
	  FROM gare g INNER JOIN v_gare_torn vgt ON g.codgar1=vgt.codgar INNER JOIN pubg p ON g.ngara=p.ngara
	 WHERE vgt.genere in (2,3) AND p.tippubg=3
	GROUP BY g.codgar1
	UNION ALL
	/* Postinformazione su profilo committente */
	SELECT g.codgar1 AS codgar, 'PG-POSTINFOPROFCOMMITT' AS codevento, MIN(p.DINPUBG) AS dataconsuntivo
	  FROM gare g INNER JOIN v_gare_torn vgt ON g.codgar1=vgt.codgar INNER JOIN pubg p ON g.ngara=p.ngara
	 WHERE vgt.genere in (2,3) AND p.tippubg=8
	GROUP BY g.codgar1
	UNION ALL
	/* Postinformazione su Sito Internet dell'Osservatorio */
	SELECT g.codgar1 AS codgar, 'PG-POSTINFOSITOOR' AS codevento, MIN(p.DINPUBG) AS dataconsuntivo
	  FROM gare g INNER JOIN v_gare_torn vgt ON g.codgar1=vgt.codgar INNER JOIN pubg p ON g.ngara=p.ngara
	 WHERE vgt.genere in (2,3) AND p.tippubg=10
	GROUP BY g.codgar1;

CREATE OR REPLACE VIEW v_scad_bandi_term AS
	/* Termine per effettuare la richiesta di chiarimenti per domanda di partecipazione */
	SELECT g.codgar, 'PG-TERMRICHCHIADOMPAR' AS codevento, dtermrichcdp AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (1,2,3)
	UNION ALL
	/* Termine per rispondere ai chiarimenti per domanda di partecipazione */
	SELECT g.codgar, 'PG-TERMRISPCHIADOMPAR' AS codevento, dtermrispcdp AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (1,2,3)
	UNION ALL
	/* Termine per effettuare la richiesta di chiarimenti per presentazione offerta */
	SELECT g.codgar, 'PG-TERMRICHCHIAPRESOFF' AS codevento, dtermrichcpo AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (1,2,3)
	UNION ALL
	/* Termine per risposta ai chiarimenti per presentazione offerta */
	SELECT g.codgar, 'PG-TERMRISPCHIAPRESOFF' AS codevento, dtermrispcpo AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (1,2,3)
	UNION ALL
	/* Termine per la presentazione delle domande di partecipazione o manifestazione d'interesse */
	SELECT g.codgar, 'PG-TERMPRESDOMPAR' AS codevento, dtepar AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (1,2,3)
	UNION ALL
	/* Termine per la comunicazione di esclusione dei concorrenti in fase di verifica delle domande di partecipazione */ 
	SELECT g.codgar, 'PG-TERMCOMESCLCONCCHKDOMPAR' AS codevento, dplettcomescl AS dataconsuntivo 
	  FROM garestati g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (2,3) AND stepgar='-25'
	UNION ALL
	 /* Termine per la presentazione delle offerte */
	SELECT g.codgar, 'PG-TERMPRESOFF' AS codevento, dteoff AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (1,2,3)
	UNION ALL
	/* Termine per la comunicazione di esclusione dei concorrenti in fase di verifica della documentazione amministrativa */
	SELECT g.codgar, 'PG-TERMCOMESCLCONCCHKDOCAMM' AS codevento, dplettcomescl AS dataconsuntivo 
	  FROM garestati g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (2,3) AND stepgar='35'
	UNION ALL
	/* Termine per la comunicazione di esclusione dei concorrenti in fase di verifica dei requisiti ex art. 48 comma 1 */
	SELECT g.codgar, 'PG-TERMCOMESCLCONCCHKREQ' AS codevento, dplettcomescl AS dataconsuntivo 
	  FROM garestati g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (2,3) AND stepgar='45'
	UNION ALL
	/* Termine per la comunicazione di esclusione dei concorrenti in fase di apertura delle offerte economiche */
	SELECT g.codgar, 'PG-TERMCOMESCLCONCCHKOFFEC' AS codevento, dplettcomescl AS dataconsuntivo 
	  FROM garestati g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (2,3) AND stepgar='60'
	 UNION ALL
	/* Termine per la comunicazione di esclusione dei concorrenti in fase di verifica delle offerte tecniche */
	SELECT g.codgar, 'PG-TERMCOMESCLCONCCHKOFFTECN' AS codevento, dplettcomescl AS dataconsuntivo 
	  FROM garestati g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (2,3) AND stepgar='55';

CREATE OR REPLACE VIEW v_scad_bandi_comunic AS
	/* Invio bando alla GUUE */
	SELECT g.codgar, 'PG-INVBANDOGUUE' AS codevento, MIN(p.DINPUB) AS dataconsuntivo
	  FROM v_gare_torn g INNER JOIN pubbli p ON g.codgar=p.codgar9 
	 WHERE g.genere IN (1,2,3) AND p.tippub=3 
	GROUP BY g.codgar
	UNION ALL
	/* Invio delle lettere d'invito */
	SELECT g.codgar, 'PG-INVLETTINVITO' AS codevento, dinvit AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (1,2,3)
	UNION ALL
	/* Invio richiesta documenti a seguito dei sorteggi per verifica dei requisiti ex art. 48 comma 1 */
	SELECT g.codgar, 'PG-INVRICHDOCSORTEGGI' AS codevento, dridoc AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (1,2,3)
	UNION ALL 
	/* Arrivo documentazione ex. art 48 comma 1 */
	SELECT g.codgar, 'PG-ARRIVODOC' AS codevento, dindoc AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (1,2,3)
	UNION ALL
	/* Arrivo documentazione aggiudicatario per congruità offerta */
	SELECT d.codgar5 AS codgar, 'PG-ARRDOCAGGCONGROFF' AS codevento, MAX(d.dricezgiu) AS dataconsuntivo 
	  FROM ditg d INNER JOIN v_gare_torn vgt ON d.codgar5=vgt.codgar
	 WHERE vgt.genere in (2,3)
	GROUP BY d.codgar5
	UNION ALL
	/* Comunicazioni di avvenuta aggiudicazione ex art. 79 comma 5 lett. a */
	SELECT g.codgar, 'PG-COMMAVVAGG' AS codevento, MAX(g.dataconsuntivo) AS dataconsuntivo 
	  FROM (
			SELECT codgar1 AS codgar, dcomag AS dataconsuntivo FROM gare WHERE dcomng IS NOT NULL AND dcomag IS NOT NULL
			UNION ALL
			SELECT codgar1 AS codgar, dcomng AS dataconsuntivo FROM gare WHERE dcomng IS NOT NULL AND dcomag IS NOT NULL
			) g
	  INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (2,3)
	GROUP BY g.codgar
	UNION ALL
	/* Invio richiesta ex art 48 comma 2 al 1° e 2° in graduatoria */
	SELECT g.codgar1 AS codgar, 'PG-INVRICHPRIMI2GRAD' AS codevento, max(g.drichdoccr) AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_torn vgt ON g.codgar1=vgt.codgar
	 WHERE vgt.genere in (2,3)
	GROUP BY g.codgar1
	UNION ALL
	/* Arrivo documentazione ex art. 48 comma  2 (requisiti speciali) da 1° e 2° in graduatoria */
	SELECT g.codgar1 AS codgar, 'PG-ARRIVODOCPRIMI2GRAD' AS codevento, max(g.dtermdoccr) AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_torn vgt ON g.codgar1=vgt.codgar
	 WHERE vgt.genere in (2,3)
	GROUP BY g.codgar1
	UNION ALL
	/* Comunicazioni di avvenuta stipula del contratto  ex art. 79 comma 5 lett. ter) */
	SELECT vgt.codgar, 'PG-COMMAVVSTIPCON' AS codevento, MAX(g.dataconsuntivo) AS dataconsuntivo 
	  FROM (
			SELECT codgar1, dcomdittagg AS dataconsuntivo FROM gare WHERE dcomdittagg IS NOT NULL AND dcomdittnag IS NOT NULL
			UNION ALL
			SELECT codgar1, dcomdittnag AS dataconsuntivo FROM gare WHERE dcomdittagg IS NOT NULL AND dcomdittnag IS NOT NULL
			) g INNER JOIN v_gare_torn vgt ON g.codgar1=vgt.codgar
	 WHERE vgt.genere in (2)
	GROUP BY vgt.codgar
	UNION ALL
	SELECT vgt.codgar, 'PG-COMMAVVSTIPCON' AS codevento, max(g.dataconsuntivo) AS dataconsuntivo 
	  FROM (
			SELECT codgar1, dcomdittagg AS dataconsuntivo FROM gare g1 WHERE dcomdittagg IS NOT NULL AND dcomdittnag IS NOT NULL AND NOT EXISTS (SELECT ngara FROM gare g2 WHERE g1.codgar1 = g2.codgar1 AND (dcomdittagg IS NULL OR dcomdittnag IS NULL))
			UNION ALL
			SELECT codgar1, dcomdittnag AS dataconsuntivo FROM gare g1 WHERE dcomdittagg IS NOT NULL AND dcomdittnag IS NOT NULL AND NOT EXISTS (SELECT ngara FROM gare g2 WHERE g1.codgar1 = g2.codgar1 AND (dcomdittagg IS NULL OR dcomdittnag IS NULL))
			) g INNER JOIN v_gare_torn vgt ON g.codgar1=vgt.codgar 
	 WHERE vgt.genere in (3)
	GROUP BY vgt.codgar;

CREATE OR REPLACE VIEW v_scad_bandi_altro AS
	/* Seduta pubblica apertura della busta A contenente la documentazione amministrativa  - considera gare a lotto unico o con plico unico*/
	SELECT g.codgar1 AS codgar, 'PG-SEDPUBBLDOCAMM' AS codevento, MIN(s.datini) AS dataconsuntivo 
	  FROM gare g INNER JOIN garsed s ON g.ngara = s.ngara
	 WHERE (g.genere is null or g.genere=3) and (g.codgar1=g.ngara or g.codgar1='$'||g.ngara) AND s.fase=2 
	GROUP BY g.codgar1
	UNION ALL
	/* Data esame documentazione ex art. 48 comma 1 */
	SELECT g.codgar, 'PG-ESAMEDOC' AS codevento, desdoc AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_torn vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere in (1,2,3)
	UNION ALL
	/* Seduta pubblica  di apertura delle offerte economiche - considera gare a lotto unico o con plico unico*/
	SELECT g.codgar1 AS codgar, 'PG-SEDPUBBLOFFEC' AS codevento, MIN(s.datini) AS dataconsuntivo 
	  FROM gare g INNER JOIN garsed s ON g.ngara = s.ngara
	 WHERE (g.genere is null or g.genere=3) and (g.codgar1=g.ngara or g.codgar1='$'||g.ngara) AND s.fase=6
	GROUP BY g.codgar1
	UNION ALL
	/* Seduta apertura offerte tecniche - considera gare a lotto unico o con plico unico*/
	SELECT g.codgar1 AS codgar, 'PG-SEDAPOFFTECN' AS codevento, MIN(s.datini) AS dataconsuntivo 
	  FROM gare g INNER JOIN garsed s ON g.ngara = s.ngara
	 WHERE (g.genere is null or g.genere=3) and (g.codgar1=g.ngara or g.codgar1='$'||g.ngara) AND s.fase=5
	GROUP BY g.codgar1
	UNION ALL
	/* Determinazione di aggiudicazione definitiva non efficace - considera gare a lotto unico o con plico unico*/
	SELECT g.codgar1 AS codgar, 'PG-AGGDEFNONEFF' AS codevento, g.dattoa AS dataconsuntivo 
		FROM gare g where (g.genere is null or g.genere=3) and (g.codgar1=g.ngara or g.codgar1='$'||g.ngara)
	UNION ALL
	/* Data stipula contrattuale - considera gare a lotto unico o con plico unico*/
	SELECT g.codgar1 AS codgar, 'PG-DATASTIPCONTR' AS codevento, max(g.daatto) AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_torn vgt ON g.codgar1=vgt.codgar
	 WHERE vgt.genere in (2,3)
	GROUP BY g.codgar1;

CREATE OR REPLACE VIEW v_scad_torn_cal AS
	SELECT T.CODGAR, G.OGGETTO || ' (gara a lotti distinti per ' || lower(T1.TAB1DESC) || ' con codice ''' || G.CODICE || ''')' AS DESCR
		FROM TORN T INNER JOIN V_GARE_GENERE G ON T.CODGAR=G.CODGAR INNER JOIN TAB1 T1 ON T.TIPGEN=T1.TAB1TIP AND T1.TAB1COD='A1007'
		AND GENERE IN (1)
	UNION ALL
	SELECT T.CODGAR, G.OGGETTO || ' (gara a lotto unico per ' || lower(T1.TAB1DESC) || ' con codice ''' || G.CODICE || ''')' AS DESCR
		FROM TORN T INNER JOIN V_GARE_GENERE G ON T.CODGAR=G.CODGAR INNER JOIN TAB1 T1 ON T.TIPGEN=T1.TAB1TIP AND T1.TAB1COD='A1007'
		AND GENERE IN (2)
	UNION ALL
	SELECT T.CODGAR, G.OGGETTO || ' (gara a lotti con offerta unica ' || lower(T1.TAB1DESC) || ' con codice ''' || G.CODICE || ''')' AS DESCR
		FROM TORN T INNER JOIN V_GARE_GENERE G ON T.CODGAR=G.CODGAR INNER JOIN TAB1 T1 ON T.TIPGEN=T1.TAB1TIP AND T1.TAB1COD='A1007'
		AND GENERE IN (3);

CREATE OR REPLACE VIEW v_scad_torn_promem AS
	SELECT CODGAR, cast('PG-BANDO-RUP' as varchar(100)) AS CODREFERENTE, EMATEC AS MAIL FROM TORN INNER JOIN TECNI ON TORN.CODRUP=TECNI.CODTEC;

CREATE OR REPLACE VIEW v_scad_lottibando_pubb AS
	/* Pubblicazione avviso su profilo committente */
	SELECT g.codice AS ngara, 'PG-LOT-PUBAVVPROFCOMMITT' AS codevento, MIN(p.DATPUB) AS dataconsuntivo 
	  FROM v_gare_genere g INNER JOIN pubbli p ON g.codgar=p.codgar9 
	 WHERE g.genere=100 AND p.tippub=8
	GROUP BY g.codice
	UNION ALL
	/* Pubblicazione avviso su quotidiani nazionali e locali */
	SELECT g.codice AS ngara, 'PG-LOT-PUBAVVQUOTNAZLOC' AS codevento, MIN(p.DATPUB) AS dataconsuntivo 
	  FROM v_gare_genere g INNER JOIN pubbli p ON g.codgar=p.codgar9 
	 WHERE g.genere=100 AND p.tippub IN (6,7)
	GROUP BY g.codice
	UNION ALL
	/* Pubblicazione sulla GUUE e invio alla GURI */
	SELECT codice AS ngara, 'PG-LOT-PUBGUUEINVGURI' AS codevento, 
		   CASE WHEN datpubguue IS NULL THEN NULL 
		   ELSE 
			 CASE WHEN datinvguri IS NULL THEN NULL 
			 ELSE 
			   CASE WHEN datpubguue > datinvguri THEN datpubguue ELSE datinvguri END 
			 END 
		   END AS dataconsuntivo 
	  FROM (
			SELECT g.codice, MIN(pguue.DATPUB) AS datpubguue, MIN(pguri.DINPUB) AS datinvguri
			  FROM v_gare_genere g LEFT OUTER JOIN pubbli pguue ON g.codgar=pguue.codgar9 LEFT OUTER JOIN pubbli pguri ON g.codgar=pguri.codgar9
			 WHERE g.genere=100 AND pguue.tippub=3 AND pguri.tippub=4
			GROUP BY g.codice
		   ) A
	UNION ALL
	/* Pubblicazione su GURI */
	SELECT codice AS ngara, 'PG-LOT-PUBGURI' AS codevento, MIN(p.DATPUB) AS dataconsuntivo 
	  FROM v_gare_genere g INNER JOIN pubbli p ON g.codgar=p.codgar9 
	 WHERE g.genere=100 AND p.tippub=4
	GROUP BY g.codice
	UNION ALL
	/* Pubblicazione su SITAT/ Min infrastrutture */
	SELECT codice AS ngara, 'PG-LOT-PUBSITATMININFRASTR' AS codevento, MIN(p.DATPUB) AS dataconsuntivo 
	  FROM v_gare_genere g INNER JOIN pubbli p ON g.codgar=p.codgar9 
	 WHERE g.genere=100 AND p.tippub IN (9,10)
	GROUP BY g.codice
	UNION ALL
	/* Postinformazione su GUUE */
	SELECT g.ngara, 'PG-LOT-POSTINFOGUUE' AS codevento, MIN(p.DINPUBG) AS dataconsuntivo
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice INNER JOIN pubg p ON g.ngara=p.ngara
	 WHERE vgt.genere=100 AND p.tippubg=3
	GROUP BY g.ngara
	UNION ALL
	/* Postinformazione su profilo committente */
	SELECT g.ngara, 'PG-LOT-POSTINFOPROFCOMMITT' AS codevento, MIN(p.DINPUBG) AS dataconsuntivo
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice INNER JOIN pubg p ON g.ngara=p.ngara
	 WHERE vgt.genere=100 AND p.tippubg=8
	GROUP BY g.ngara
	UNION ALL
	/* Postinformazione su Sito Internet dell'Osservatorio */
	SELECT g.ngara, 'PG-LOT-POSTINFOSITOOR' AS codevento, MIN(p.DINPUBG) AS dataconsuntivo
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice INNER JOIN pubg p ON g.ngara=p.ngara
	 WHERE vgt.genere=100 AND p.tippubg=10
	GROUP BY g.ngara;

CREATE OR REPLACE VIEW v_scad_lottibando_term AS
	/* Termine per effettuare la richiesta di chiarimenti per domanda di partecipazione */
	SELECT vgt.codice AS ngara, 'PG-LOT-TERMRICHCHIADOMPAR' AS codevento, dtermrichcdp AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_genere vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere=100
	UNION ALL
	/* Termine per rispondere ai chiarimenti per domanda di partecipazione */
	SELECT vgt.codice AS ngara, 'PG-LOT-TERMRISPCHIADOMPAR' AS codevento, dtermrispcdp AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_genere vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere=100
	UNION ALL
	/* Termine per effettuare la richiesta di chiarimenti per presentazione offerta per i lotti di gare con offerte distinte */
	SELECT ngara, 'PG-LOT-TERMRICHCHIAPRESOFF' AS codevento, dtermrichcpog AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100
	UNION ALL
	/* Termine per risposta ai chiarimenti per presentazione offerta per i lotti di gare con offerte distinte */
	SELECT ngara, 'PG-LOT-TERMRISPCHIAPRESOFF' AS codevento, dtermrispcpog AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100
	UNION ALL
	/* Termine per la presentazione delle domande di partecipazione o manifestazione d'interesse */
	SELECT vgt.codice AS ngara, 'PG-LOT-TERMPRESDOMPAR' AS codevento, dtepar AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_genere vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere=100
	UNION ALL
	/* Termine per la comunicazione di esclusione dei concorrenti in fase di verifica delle domande di partecipazione */ 
	SELECT ngara, 'PG-LOT-TERMCOMESCLCONCCHKDOMPAR' AS codevento, dplettcomescl AS dataconsuntivo 
	  FROM garestati g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100 AND stepgar='-25'
	UNION ALL
	/* Termine per la presentazione delle offerte per i lotti di gare con offerte distinte */
	SELECT ngara, 'PG-LOT-TERMPRESOFF' AS codevento, dteoff AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100
	UNION ALL
	/* Termine per la comunicazione di esclusione dei concorrenti in fase di verifica della documentazione amministrativa */
	SELECT ngara, 'PG-LOT-TERMCOMESCLCONCCHKDOCAMM' AS codevento, dplettcomescl AS dataconsuntivo 
	  FROM garestati g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100 AND stepgar='35'
	UNION ALL
	/* Termine per la comunicazione di esclusione dei concorrenti in fase di verifica dei requisiti ex art. 48 comma 1 */
	SELECT ngara, 'PG-LOT-TERMCOMESCLCONCCHKREQ' AS codevento, dplettcomescl AS dataconsuntivo 
	  FROM garestati g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100 AND stepgar='45'
	UNION ALL
	/* Termine per la comunicazione di esclusione dei concorrenti in fase di apertura delle offerte economiche */
	SELECT ngara, 'PG-LOT-TERMCOMESCLCONCCHKOFFEC' AS codevento, dplettcomescl AS dataconsuntivo 
	  FROM garestati g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100 AND stepgar='60'
	UNION ALL
	/* Termine per la comunicazione di esclusione dei concorrenti in fase di verifica delle offerte tecniche */
	SELECT ngara, 'PG-LOT-TERMCOMESCLCONCCHKOFFTECN' AS codevento, dplettcomescl AS dataconsuntivo 
	  FROM garestati g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100 AND stepgar='55';

CREATE OR REPLACE VIEW v_scad_lottibando_comunic AS
	/* Invio bando alla GUUE */
	SELECT g.codice AS ngara, 'PG-LOT-INVBANDOGUUE' AS codevento, MIN(p.DINPUB) AS dataconsuntivo
	  FROM v_gare_genere g INNER JOIN pubbli p ON g.codgar=p.codgar9 
	 WHERE g.genere=100 AND p.tippub=3 
	GROUP BY g.codice
	UNION ALL
	/* Invio delle lettere d'invito per i lotti di gare con offerte distinte */
	SELECT ngara, 'PG-LOT-INVLETTINVITO' AS codevento, dinvit AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100
	UNION ALL
	/* Invio richiesta documenti a seguito dei sorteggi per verifica dei requisiti ex art. 48 comma 1 */
	SELECT vgt.codice AS ngara, 'PG-LOT-INVRICHDOCSORTEGGI' AS codevento, dridoc AS dataconsuntivo 
	  FROM torn g INNER JOIN v_gare_genere vgt ON g.codgar=vgt.codgar
	 WHERE vgt.genere=100
	UNION ALL 
	/* Arrivo documentazione ex. art 48 comma 1 del lotto */
	SELECT ngara, 'PG-LOT-ARRIVODOC' AS codevento, dindoc AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100
	 UNION ALL
	/* Arrivo documentazione aggiudicatario per congruità offerta */
	SELECT vgt.codice AS ngara, 'PG-LOT-ARRDOCAGGCONGROFF' AS codevento, MAX(d.dricezgiu) AS dataconsuntivo 
	  FROM ditg d INNER JOIN v_gare_genere vgt ON d.ngara5=vgt.codice
	 WHERE vgt.genere=100
	GROUP BY vgt.codice
	UNION ALL
	/* Comunicazioni di avvenuta aggiudicazione ex art. 79 comma 5 lett. a */
	SELECT g.ngara, 'PG-LOT-COMMAVVAGG' AS codevento, MAX(g.dataconsuntivo) AS dataconsuntivo 
	  FROM (
			SELECT ngara, dcomag AS dataconsuntivo FROM gare WHERE dcomng IS NOT NULL AND dcomag IS NOT NULL
			UNION ALL
			SELECT ngara, dcomng AS dataconsuntivo FROM gare WHERE dcomng IS NOT NULL AND dcomag IS NOT NULL
			) g
	  INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100
	GROUP BY g.ngara
	UNION ALL
	/* Invio richiesta ex art 48 comma 2 al 1° e 2° in graduatoria */
	SELECT ngara, 'PG-LOT-INVRICHPRIMI2GRAD' AS codevento, g.drichdoccr AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100
	UNION ALL
	/* Arrivo documentazione ex art. 48 comma  2 (requisiti speciali) da 1° e 2° in graduatoria */
	SELECT ngara, 'PG-LOT-ARRIVODOCPRIMI2GRAD' AS codevento, g.dtermdoccr AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100
	UNION ALL
	/* Comunicazioni di avvenuta stipula del contratto  ex art. 79 comma 5 lett. ter) */
	SELECT g.ngara, 'PG-LOT-COMMAVVSTIPCON' AS codevento, MAX(g.dataconsuntivo) AS dataconsuntivo 
	  FROM (
			SELECT ngara, dcomdittagg AS dataconsuntivo FROM gare WHERE dcomdittagg IS NOT NULL AND dcomdittnag IS NOT NULL
			UNION ALL
			SELECT ngara, dcomdittnag AS dataconsuntivo FROM gare WHERE dcomdittagg IS NOT NULL AND dcomdittnag IS NOT NULL
			) g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100
	GROUP BY g.ngara;

CREATE OR REPLACE VIEW v_scad_lottibando_altro AS
	/* Seduta pubblica apertura della busta A contenente la documentazione amministrativa */
	SELECT l.ngara, 'PG-LOT-SEDPUBBLDOCAMM' AS codevento, MIN(s.datini) AS dataconsuntivo 
	  FROM v_gare_genere vgt INNER JOIN gare l ON vgt.codice = l.ngara INNER JOIN garsed s ON l.ngara = s.ngara
	 WHERE vgt.genere=100 AND s.fase=2
	GROUP BY l.ngara
	UNION ALL
	/* Data esame documentazione ex art. 48 comma 1 del lotto */
	SELECT ngara, 'PG-LOT-ESAMEDOC' AS codevento, desdoc AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100
	UNION ALL
	/* Seduta pubblica di apertura delle offerte economiche */
	SELECT l.ngara, 'PG-LOT-SEDPUBBLOFFEC' AS codevento, MIN(s.datini) AS dataconsuntivo 
	  FROM v_gare_genere vgt INNER JOIN gare l ON vgt.codice = l.ngara INNER JOIN garsed s ON l.ngara = s.ngara
	 WHERE vgt.genere=100 AND s.fase=6
	GROUP BY l.ngara
	UNION ALL
	/* Seduta apertura offerte tecniche */
	SELECT l.ngara, 'PG-LOT-SEDAPOFFTECN' AS codevento, MIN(s.datini) AS dataconsuntivo 
	  FROM v_gare_genere vgt INNER JOIN gare l ON vgt.codice = l.ngara INNER JOIN garsed s ON l.ngara = s.ngara
	 WHERE vgt.genere=100 AND s.fase=5
	GROUP BY l.ngara
	UNION ALL
	/* Determinazione di aggiudicazione definitiva non efficace */
	SELECT ngara, 'PG-LOT-AGGDEFNONEFF' AS codevento, g.dattoa AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100
	UNION ALL
	/* Data stipula contrattuale */
	SELECT ngara, 'PG-LOT-DATASTIPCONTR' AS codevento, g.daatto AS dataconsuntivo 
	  FROM gare g INNER JOIN v_gare_genere vgt ON g.ngara=vgt.codice
	 WHERE vgt.genere=100;
	 
CREATE OR REPLACE VIEW v_scad_gare_cal AS
	SELECT L.NGARA, 'Lotto di gara con codice ''' || L.NGARA || ''', oggetto ''' || L.CODIGA || ''', cig ' || case when L.CODCIG is null then 'non valorizzato' else '''' || L.CODCIG || '''' end || ', della gara ''' || T.DESTOR || '''' AS DESCR 
	FROM GARE L INNER JOIN V_GARE_GENERE G ON L.NGARA=G.CODICE INNER JOIN TORN T ON L.CODGAR1=T.CODGAR
	AND G.GENERE = 100;

CREATE OR REPLACE VIEW v_scad_gare_promem AS
	SELECT NGARA, cast('PG-BANDO-RUP' as varchar(100)) AS CODREFERENTE, EMATEC AS MAIL FROM GARE INNER JOIN TORN ON GARE.CODGAR1=TORN.CODGAR INNER JOIN TECNI ON TORN.CODRUP=TECNI.CODTEC;

