-- (C.F. - 03.04.09) Elenco dei plichi da ritirare  
--
create or replace view v_ditte_prit (CODGAR, NGARA, TIPPROT, DITTAO, NPROGG, NOMIMO, PROTOCOLLO, DATAP, ORAP, RITIRO,UTENTE) as
	(select d.codgar5,d.ngara5,1,d.dittao,d.nprogg,d.nomimo,d.nprdom as protocollo,d.dricind as datap,d.oradom as orap,coalesce(d.ritdom,0) as ritiro,d.scrdom as utente
      from ditg d
         where nprdom is not null and (ritdom is null or ritdom<2)
     union
     select d.codgar5,d.ngara5,2,d.dittao,d.nprogg,d.nomimo,d.nproff as protocollo,d.datoff as datap,d.oraoff as orap,coalesce(d.ritoff,0) as ritiro,d.scroff as utente
      from ditg d
          where d.nproff is not null and d.ritdom =2 and (d.ritoff is null or d.ritoff<2)
     union
     select d.codgar5,d.ngara5,2,d.dittao,d.nprogg,d.nomimo,d.nproff as protocollo,d.datoff as datap,d.oraoff as orap,coalesce(d.ritoff,0) as ritiro,d.scroff as utente
      from ditg d
          where d.nproff is not null and d.nprdom is null and (d.ritoff is null or d.ritoff<2)
     union
     select d.codgar5,d.ngara5,3,d.dittao,d.nprogg,d.nomimo,d.nprreq as protocollo,d.datreq as datap,d.orareq as orap,coalesce(d.ritreq,0) as ritiro,d.scrreq as utente
      from ditg d where nprreq is not null and ritoff=2 and (ritreq is null or ritreq<2) );

-- (C.F. - 03.04.09) Elenco dei lotti di gara.
--
create or replace view v_gare_terms (codgar,ngara,tipgen,tipgarg,oggetto,impapp,dtepar,otepar,dteoff,oteoff,dindoc,is_spdom,is_spoff,is_spdoc) as
	(select t.codgar,g.ngara,t.tipgen,g.tipgarg,ge.oggetto,g.impapp,coalesce(g.dteparg,t.dtepar),coalesce(g.oteparg,t.otepar),coalesce(g.dteoff,t.dteoff),coalesce(g.oteoff,t.oteoff),coalesce(g.dindoc,t.dindoc),
        CASE greatest(now(),coalesce(coalesce(g.dteparg,t.dtepar),now() - interval  '1 day' * (to_number(t1.tab1desc,'9999D0000')+1)  ) + interval  '1 day' * to_number(t1.tab1desc,'9999D0000'))
              WHEN now()
              THEN cast('1' as varchar(1))
              ELSE cast('2' as varchar(1))
              END AS is_spdom,
        CASE greatest(now(),coalesce(coalesce(g.dteoff,t.dteoff),now() - interval  '1 day' * (to_number(t2.tab1desc,'9999D0000')+1)  ) + interval  '1 day' * to_number(t2.tab1desc,'9999D0000'))
              WHEN now()
              THEN cast('1' as varchar(1))
              ELSE cast('2' as varchar(1))
              END AS is_spoff,
        CASE greatest(now(),coalesce(coalesce(g.dindoc,t.dindoc),now() - interval  '1 day' * (to_number(t3.tab1desc,'9999D0000')+1)  ) + interval  '1 day' * to_number(t3.tab1desc,'9999D0000'))
              WHEN now()
              THEN cast('1' as varchar(1))
              ELSE cast('2' as varchar(1))
              END AS is_spdoc                
      from gare g,torn t,v_gare_genere ge,tab1 t1,tab1 t2,tab1 t3  where t.codgar=g.codgar1
	and t.codgar=ge.codgar and g.ngara=ge.codice and ge.genere in (100,2,3)
       and t1.tab1cod='A1042' and t1.tab1tip=1
       and t2.tab1cod='A1042' and t2.tab1tip=2 
       and t3.tab1cod='A1042' and t3.tab1tip=3 );

-- (C.F. - 10.11.09) Elenco delle gare in scadenza 
--
create or replace view v_gare_nscad (codgar,ngara,tipgen,tipgarg,oggetto,impapp,dtepar,dteoff,dindoc,tipscad,datascad,orascad) as
	(select v.codgar,v.ngara,v.tipgen,v.tipgarg,v.oggetto,v.impapp,v.dtepar,v.dteoff,v.dindoc,1,v.dtepar,v.otepar
       from v_gare_terms v  where is_spdom='2' 
       union
     select v.codgar,v.ngara,v.tipgen,v.tipgarg,v.oggetto,v.impapp,v.dtepar,v.dteoff,v.dindoc,2,v.dteoff,v.oteoff
       from v_gare_terms v  where is_spdom='1' and is_spoff='2'
       union
     select v.codgar,v.ngara,v.tipgen,v.tipgarg,v.oggetto,v.impapp,v.dtepar,v.dteoff,v.dindoc,3,v.dindoc,null
       from v_gare_terms v  where is_spdom='1' and is_spoff='1' and is_spdoc='2');

-- (S.Santi 28.11.2017) View documenti da firmare, utilizzata da applicativi esterni
create or replace view v_gare_docfirma as
	--documenti della gara
	select (case when documgara.codgar like '$%' then documgara.ngara else documgara.codgar end) codicegara,
	(case when documgara.codgar like '$%' then gare.not_gar else torn.destor end) oggetto,
	'Documento gara' tipo, documgara.descrizione,
	 w_docdig.dignomdoc nomefile, w_docdig.idprg, w_docdig.iddocdig
	from w_docdig
	inner join documgara on (documgara.idprg=w_docdig.idprg and documgara.iddocdg=w_docdig.iddocdig )
	inner join torn on (documgara.codgar=torn.codgar)
	left outer join gare on (gare.ngara=documgara.ngara)
	where w_docdig.digfirma='1'
	union
	--allegati comunicazioni in bozza, sia pubbliche che riservate
	select (case when torn.codgar like '$%' then gare.ngara else torn.codgar end), 
	(case when torn.codgar like '$%' then gare.not_gar else torn.destor end),
	'Allegato comunicazione', w_docdig.digdesdoc,
	w_docdig.dignomdoc, w_docdig.idprg, w_docdig.iddocdig
	from w_docdig,w_invcom,gare,torn
	where torn.codgar=gare.codgar1 and gare.ngara=w_invcom.comkey1 and w_docdig.digent='W_INVCOM' and w_invcom.idprg=w_docdig.digkey1 and CAST(w_invcom.idcom AS VARCHAR(12))=w_docdig.digkey2
	and w_invcom.comstato='1' 
	and w_docdig.digfirma='1'
	union
	--documenti associati TORN
	select torn.codgar, torn.destor,
	'Documento associato', c0oggass.c0atit,
	w_docdig.dignomdoc, w_docdig.idprg, w_docdig.iddocdig
	from w_docdig, c0oggass, torn
	where c0aent='TORN' and c0oggass.c0akey1=torn.codgar and w_docdig.digent='C0OGGASS' and CAST(c0oggass.c0acod AS VARCHAR(10))=w_docdig.digkey1 
	and w_docdig.digfirma='1'
	union
	--documenti associati GARE
	select (case when torn.codgar like '$%' then gare.ngara else torn.codgar end), 
	(case when torn.codgar like '$%' then gare.not_gar else torn.destor end),
	'Documento associato',  c0oggass.c0atit,
	w_docdig.dignomdoc, w_docdig.idprg, w_docdig.iddocdig
	from w_docdig, c0oggass, gare, torn
	where c0aent='GARE' and c0oggass.c0akey1=gare.ngara and torn.codgar=gare.codgar1 and w_docdig.digent='C0OGGASS' and CAST(c0oggass.c0acod AS VARCHAR(10))=w_docdig.digkey1
	and w_docdig.digfirma='1';

-- View documenti da firmare per utente
create or replace view v_gare_docfirma_utenti as 
	select usrsys.syscon, usrsys.syscf, usrsys.sysute,
	 v_gare_docfirma.codicegara, v_gare_docfirma.oggetto, v_gare_docfirma.tipo, v_gare_docfirma.descrizione,
	 v_gare_docfirma.nomefile,v_gare_docfirma.idprg,v_gare_docfirma.iddocdig
	 from usrsys, g_permessi, v_gare_docfirma
	 where usrsys.syscon=g_permessi.syscon 
	 and (g_permessi.codgar=v_gare_docfirma.codicegara or g_permessi.codgar='$'||v_gare_docfirma.codicegara);

-- View per processo di analisi DGUE con M-DGUE
create or replace view v_dgueelabsub as
	select distinct de.codgar,
	de.ngara,
	de.codimp,
	de.id idelaborazione,
	bd.busta,
	b.iddocdig,
	de.dignomdoc,
	de.esclusione,
	de.nomeoe,
	de.cf,
	de.piva,
	coalesce(de.nomeoe || '#!#','')   || coalesce('CF: ' || de.cf || '#!#','')  || coalesce('P.Iva/Id fisc.: ' ||de.piva,'') ditta,
	de.ruolo,
	de.isgruppo,
	de.nomegruppo,
	de.componenti,
	de.isconsorzio,
	de.consorziate,
	(select array_to_string(array_agg(coalesce(dgue_elabsub.denominazione,'') || coalesce(' (' || dgue_elabsub.cf || ') - ','') || coalesce(dgue_elabsub.attivita || ', ','') || coalesce(dgue_elabsub.prestazione,'')|| coalesce(' (' ||dgue_elabsub.quota::text || '%)','') ),';#!#') from  dgue_elabsub where ruolo=1 and idelaborazione=de.id ) sub,
	(select array_to_string(array_agg(coalesce(dgue_elabsub.denominazione,'') || coalesce(' (' || dgue_elabsub.cf || ') - ','') || coalesce(dgue_elabsub.attivita,'')) ,';#!#') from  dgue_elabsub where ruolo=2 and idelaborazione=de.id ) aux,
	t.tab5nord
	from dgue_elaborazioni de left join dgue_elabsub des on des.idelaborazione=de.id join dgue_batch_doc b on b.id=de.idbatchdoc join dgue_batch bd on b.idbatch=bd.id left join tab5 t on de.ruolo=t.tab5cod and t.tab5cod='G1j01'
	where de.idbatch in (select max(id) from dgue_batch group by codimp, codgar, busta);

