INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (1,'PG','A1073',1,'Presenta gli operatori in ordine inverso rispetto agli inviti accumulati sulla categoria o prestazione prevalente della gara, alle penalità assegnate dall''ente e al numero di inviti virtuali accreditati al momento dell''attivazione in elenco. A parità di numero di inviti e penalità, gli operatori sono ordinati secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (2,'PG','A1073',2,'Presenta gli operatori ordinati secondo il numero ordine assegnato in elenco. Presuppone che il numero ordine venga assegnato mediante estrazione casuale prima della selezione degli operatori in gara.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (3,'PG','A1073',3,'Presenta gli operatori in ordine inverso rispetto agli inviti accumulati sulla categoria o prestazione prevalente della gara e alle penalità assegnate dall''ente. A parità di numero di inviti e penalità, gli operatori sono ordinati secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (4,'PG','A1073',4,'Presenta gli operatori in ordine inverso rispetto agli inviti accumulati sulla categoria o prestazione prevalente della gara e sulla relativa classe e alle penalità assegnate dall''ente. A parità di numero di inviti e penalità, gli operatori sono ordinati secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (5,'PG','A1073',5,'Presenta gli operatori in ordine inverso rispetto agli inviti accumulati sulla categoria o prestazione prevalente della gara e sulla relativa classe, alle penalità assegnate dall''ente e al numero di inviti virtuali accreditati al momento dell''attivazione in elenco. A parità di numero di inviti e penalità, gli operatori sono ordinati secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (6,'PG','A1073',6,'Presenta gli operatori in ordine inverso rispetto agli inviti ricevuti e alle penalità assegnate dall''ente. A parità di numero di inviti e penalità, gli operatori sono ordinati secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (7,'PG','A1073',7,'Presenta gli operatori in ordine inverso rispetto agli inviti ricevuti, alle penalità assegnate dall''ente e al numero di inviti virtuali accreditati al momento dell''attivazione in elenco. A parità di numero di inviti e penalità, gli operatori sono ordinati secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (8,'PG','A1073',8,'Presenta gli operatori in ordine inverso rispetto agli inviti ricevuti nell''ambito della stazione appaltante della gara e alle penalità assegnate dall''ente. A parità di numero di inviti e penalità, gli operatori sono ordinati secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (9,'PG','A1073',9,'Presenta gli operatori in ordine inverso rispetto agli inviti ricevuti nell''ambito della stazione appaltante della gara, alle penalità assegnate dall''ente e al numero di inviti virtuali accreditati al momento dell''attivazione in elenco. A parità di numero di inviti e penalità, gli operatori sono ordinati secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (10,'PG','A1073',10,'Presenta gli operatori in ordine inverso rispetto al numero di affidamenti ottenuti e alle penalità assegnate dall''ente. A parità di numero di affidamenti e penalità, gli operatori sono ordinati secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (11,'PG','A1073',11,'Presenta gli operatori in ordine inverso rispetto al numero di affidamenti ottenuti sulla categoria o prestazione prevalente della gara e alle penalità assegnate dall''ente. A parità di numero di affidamenti e penalità, gli operatori sono ordinati secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (12,'PG','A1073',12,'Presenta gli operatori in ordine inverso rispetto al numero di affidamenti ottenuti sulla categoria o prestazione prevalente della gara e sulla relativa classe e alle penalità assegnate dall''ente. A parità di numero di affidamenti e penalità, gli operatori sono ordinati secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (13,'PG','A1073',13,'Presenta gli operatori in ordine inverso rispetto al numero di affidamenti ottenuti e alle penalità assegnate dall''ente. A parità di numero di affidamenti e penalità, gli operatori sono ordinati secondo gli inviti ricevuti e, a parità di quest''ultimi, secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (14,'PG','A1073',14,'Presenta gli operatori in ordine inverso rispetto al numero di affidamenti ottenuti sulla categoria o prestazione prevalente della gara e alle penalità assegnate dall''ente. A parità di numero di affidamenti e penalità, gli operatori sono ordinati secondo gli inviti ricevuti sulla categoria e, a parità di quest''ultimi, secondo il numero ordine assegnato in elenco.');
INSERT INTO ALGORITMI (NUMALGO,CODAPP,CODALGO,TIPOALGO,DESCALGO) VALUES (15,'PG','A1073',15,'Presenta gli operatori in ordine inverso rispetto al numero di affidamenti ottenuti sulla categoria o prestazione prevalente della gara e sulla relativa classe e alle penalità assegnate dall''ente. A parità di numero di affidamenti e penalità, gli operatori sono ordinati secondo gli inviti ricevuti sulla categoria e relativa classe e, a parità di quest''ultimi, secondo il numero ordine assegnato in elenco.');
