INSERT INTO G_EVENTISCADENZ (COD,PRG,ENT,DISCR,TIT,DESCR,FROMVIEW,NOTE) VALUES ('PG-PUBSITATMININFRASTR','PG','TORN','BANDO','Pubblicazione su SITAT/ Min infrastrutture','Viene selezionato il campo "data di pubblicazione" nella pagina "pubblicazione bando" della gara o  comune a tutti i lotti, dove il tipo pubblicazione corrisponde a "Pubblicazione al Ministero Infrastrutture e trasporti" o sul "Sito dell''Osservatorio". Ne','V_SCAD_BANDI_PUBB','Utilizzato per tutte le tipologie di gara');
INSERT INTO G_EVENTISCADENZ (COD,PRG,ENT,DISCR,TIT,DESCR,FROMVIEW,NOTE) VALUES ('PG-SEDAPOFFTECN','PG','TORN','BANDO','Seduta apertura offerte tecniche','Viene selezionato il campo "data della seduta di gara" della scheda "sedute di gara" della gara o del lotto, dove il tipo di fase è "Verifica offerte tecniche". Nel caso di più sedute, viene scelto il record con data minore.','V_SCAD_BANDI_ALTRO','Utilizzato per tutte le tipologie di gara');
INSERT INTO G_EVENTISCADENZ (COD,PRG,ENT,DISCR,TIT,DESCR,FROMVIEW,NOTE) VALUES ('PG-SEDPUBBLDOCAMM','PG','TORN','BANDO','Seduta pubblica apertura della busta A contenente la documentazione amministrativa','Viene selezionato il campo "data della seduta di gara" della scheda "sedute di gara" della gara o del lotto, dove il tipo di fase è "Apertura documentazione amministrativa". Nel caso di più sedute, viene scelto il record con data minore.','V_SCAD_BANDI_ALTRO','Utilizzato per gare a lotto unico o più lotti con offerta unica');
INSERT INTO G_EVENTISCADENZ (COD,PRG,ENT,DISCR,TIT,DESCR,FROMVIEW,NOTE) VALUES ('PG-SEDPUBBLOFFEC','PG','TORN','BANDO','Seduta pubblica di apertura delle offerte economiche','Viene selezionato il campo "data della seduta di gara" della scheda "sedute di gara" della gara o del lotto, dove il tipo di fase è "Apertura offerte economiche". Nel caso di più sedute, viene scelto il record con data minore.','V_SCAD_BANDI_ALTRO','Utilizzato per gare a lotto unico o più lotti con offerta unica');
