INSERT INTO W_CONFCOM (NUMPRO,GENERE,MODTIT,MODDESC,NUMORD,COMINTEST,COMMSGOGG,COMMSGTES,FILTROSOG,CRITTES) VALUES (28,2,'Comunicazione della convocazione per la stipula del contratto alla ditta aggiudicataria','Viene inviata alla ditta aggiudicataria',8,'1','Convocazione per la stipula del contratto','con la presente si comunica la convocazione per la stipula del contratto per la procedura d''appalto in data __________','exists (select gare.ngara from gare where gare.ngara=ditg.ngara5 and ditg.dittao = gare.ditta)',0);
