INSERT INTO W_CONFIG (CODAPP,CHIAVE,VALORE,SEZIONE,DESCRIZIONE,CRIPTATO) VALUES ('PG','it.eldasoft.accessoAnonimo','0','Accesso anonimo (DEPRECATA)','(DEPRECATA) Se impostata a 1 presenta il link nella pagina di login per accedere all''applicativo con un accesso anonimo; se impostata a 0 o non valorizzata, non presenta il link',NULL);
INSERT INTO W_CONFIG (CODAPP,CHIAVE,VALORE,SEZIONE,DESCRIZIONE,CRIPTATO) VALUES ('PG','it.eldasoft.accessoAnonimo.account',NULL,'Accesso anonimo (DEPRECATA)','(DEPRECATA) Account in USRSYS per effettuare l''accesso anonimo (da valorizzare solo se it.eldasoft.accessoAnonimo=1)',NULL);
INSERT INTO W_CONFIG (CODAPP,CHIAVE,VALORE,SEZIONE,DESCRIZIONE,CRIPTATO) VALUES ('PG','it.eldasoft.accessoAnonimo.etichettaLink','Accesso anonimo','Accesso anonimo (DEPRECATA)','(DEPRECATA) Etichetta da visualizzare nel link per l''accesso anonimo (da valorizzare solo se it.eldasoft.accessoAnonimo=1)',NULL);
INSERT INTO W_CONFIG (CODAPP,CHIAVE,VALORE,SEZIONE,DESCRIZIONE,CRIPTATO) VALUES ('PG','it.eldasoft.accessoDiretto','0','Accesso diretto (DEPRECATA)','(DEPRECATA) Abilita l''accesso (mediante url specifica) senza autenticazione con login/password ma mediante la sola verifica della login. Se impostata a 1, attiva la url per l''accesso diretto (default = 0)',NULL);
INSERT INTO W_CONFIG (CODAPP,CHIAVE,VALORE,SEZIONE,DESCRIZIONE,CRIPTATO) VALUES ('PG','it.eldasoft.accessoDiretto.parametri.obbligatori',NULL,'Accesso diretto (DEPRECATA)','(DEPRECATA) Sottoelenco dei parametri obbligatori da inviare all''accesso, separati da ";" Tale elenco è un sottoinsieme di quello specificato in "it.eldasoft.accessoDiretto.parametri"',NULL);
INSERT INTO W_CONFIG (CODAPP,CHIAVE,VALORE,SEZIONE,DESCRIZIONE,CRIPTATO) VALUES ('PG','it.eldasoft.associazioneGruppiDisabilitata','1','Configurazione generale','Property per disabilitare i gruppi nelle maschere in cui i gruppi stessi rappresentano dati in associativa (amministrazione ricerche e modelli). Valori ammessi: 1 [default] = gruppi disabilitati, 0 = gruppi abilitati (solo Report Console)',NULL);
INSERT INTO W_CONFIG (CODAPP,CHIAVE,VALORE,SEZIONE,DESCRIZIONE,CRIPTATO) VALUES ('PG','it.eldasoft.associazioneUffintAbilitata','0','Configurazione generale','Property per abilitare/disabilitare l''associazione degli utenti agli uffici intestatari e la conseguente pagina di selezione ufficio intestatario dopo la scelta del profilo',NULL);
INSERT INTO W_CONFIG (CODAPP,CHIAVE,VALORE,SEZIONE,DESCRIZIONE,CRIPTATO) VALUES ('PG','it.eldasoft.associazioneUffintAbilitata.archiviFiltrati',NULL,'Configurazione generale','Property per indicare quali sono gli archivi che vanno filtrati per ufficio intestatario (es.: IMPR;TECNI;TEIM)',NULL);
INSERT INTO W_CONFIG (CODAPP,CHIAVE,VALORE,SEZIONE,DESCRIZIONE,CRIPTATO) VALUES ('PG','it.eldasoft.bloccoEliminazioneEntita.elencoEntita','GARE;TORN;GAREALBO;GAREAVVISI','Configurazione generale','Consente di indicare quali entità devono essere bloccate in eliminazione se è stato attivato fra le opzioni utente il blocco eliminazione su entita principale (es.: GARE;TORN;GAREALBO;GAREAVVISI)',NULL);
