INSERT INTO W_CONFIG (CODAPP,CHIAVE,VALORE,SEZIONE,DESCRIZIONE,CRIPTATO) VALUES ('PG','it.eldasoft.idApplicazioneMaster','pg','Configurazione generale','Identificativo univoco da comunicare al Web Service ''compositore modelli'' per individuare tra le tante applicazioni web chi è il richiedente di un servizio, in modo da poter individuare la connessione al db e l''area su filesystem. Modificare il valore in caso di più installazioni dello stesso applicativo ma su database differenti e che interagiscono con il WSCompositore',NULL);
