Insert into G1CF_PUBB (ID,NOME,NUMORD,CL_WHERE_VIS,GRUPPO,INVIOSCP) values (111,'Deliberazione affidamento e contratto a società in house per affidamenti sopra soglia del servizio pubblico locale (art.31 DLgs.201/2022)',210,'(GARE.GENERE is null or GARE.GENERE not in (10,11,20)) and exists(select * from tab2 where tab2cod=''A1z11'' and ('',''||tab2d2||'','' like ''%,''||cast(gare.tipgarg as text)||'',%'' or '',''||tab2d2||'','' like ''%,''||cast(torn.tipgar as text)||'',%'') and (tab2tip IN (''16''))) and ((torn.settore=''O'' and torn.tipgen=1 and exists(select * from v_gare_importi where ((v_gare_importi.codgar=torn.codgar and v_gare_importi.ngara is null) or v_gare_importi.ngara=gare.ngara) and valmax>=5538000)) or (torn.settore=''O'' and torn.tipgen in (2,3) and exists(select * from v_gare_importi where ((v_gare_importi.codgar=torn.codgar and v_gare_importi.ngara is null) or v_gare_importi.ngara=gare.ngara) and valmax>=221000)) or (torn.settore=''S'' and torn.tipgen=1 and exists(select * from v_gare_importi where ((v_gare_importi.codgar=torn.codgar and v_gare_importi.ngara is null) or v_gare_importi.ngara=gare.ngara) and valmax>=5538000)) or (torn.settore=''S'' and torn.tipgen in (2,3) and exists(select * from v_gare_importi where ((v_gare_importi.codgar=torn.codgar and v_gare_importi.ngara is null) or v_gare_importi.ngara=gare.ngara) and valmax>=443000)))',4,'2');
